	mSyntaxWarmupTaskId = 0;
	mSyntaxWarmupDocumentId = 0;
	mSyntaxWarmupVersion = 0;
	mSyntaxWarmupTopLine = 0;
	mSyntaxWarmupBottomLine = 0;
