namespace {

int tabDisplayWidth(const MREditSetupSettings &settings, int visualColumn) noexcept {
	const int currentColumn = std::max(1, visualColumn + 1);
	const int targetColumn = resolvedEditFormatTabDisplayColumn(settings.formatLine, settings.tabSize, settings.leftMargin, settings.rightMargin, currentColumn);
	return std::max(1, targetColumn - currentColumn);
}

bool nextDisplayChar(TStringView text, std::size_t &index, std::size_t &width, int visualColumn, const MREditSetupSettings &settings) noexcept {
	if (index >= text.size()) return false;
	if (text[index] == '\t') {
		++index;
		width = static_cast<std::size_t>(tabDisplayWidth(settings, visualColumn));
		return true;
	}
	return TText::next(text, index, width);
}

std::string utf8FromCodepoint(std::uint32_t codepoint) {
	char bytes[5] = {0, 0, 0, 0, 0};
	if (codepoint <= 0x7F) {
		bytes[0] = static_cast<char>(codepoint);
		return std::string(bytes, 1);
	}
	if (codepoint <= 0x7FF) {
		bytes[0] = static_cast<char>(0xC0 | ((codepoint >> 6) & 0x1F));
		bytes[1] = static_cast<char>(0x80 | (codepoint & 0x3F));
		return std::string(bytes, 2);
	}
	if (codepoint <= 0xFFFF) {
		bytes[0] = static_cast<char>(0xE0 | ((codepoint >> 12) & 0x0F));
		bytes[1] = static_cast<char>(0x80 | ((codepoint >> 6) & 0x3F));
		bytes[2] = static_cast<char>(0x80 | (codepoint & 0x3F));
		return std::string(bytes, 3);
	}
	bytes[0] = static_cast<char>(0xF0 | ((codepoint >> 18) & 0x07));
	bytes[1] = static_cast<char>(0x80 | ((codepoint >> 12) & 0x3F));
	bytes[2] = static_cast<char>(0x80 | ((codepoint >> 6) & 0x3F));
	bytes[3] = static_cast<char>(0x80 | (codepoint & 0x3F));
	return std::string(bytes, 4);
}

const std::array<std::string, 256> &brailleGlyphTable() {
	static const std::array<std::string, 256> table = []() {
		std::array<std::string, 256> generated;
		generated[0] = " ";
		for (std::size_t i = 1; i < generated.size(); ++i)
			generated[i] = utf8FromCodepoint(static_cast<std::uint32_t>(0x2800 + i));
		return generated;
	}();
	return table;
}

std::size_t scaledMidpoint(std::size_t sampleIndex, std::size_t sampleCount, std::size_t targetCount) noexcept {
	if (sampleCount == 0 || targetCount == 0) return 0;
	unsigned long long numerator = static_cast<unsigned long long>(sampleIndex) * 2ull + 1ull;
	unsigned long long scaled = numerator * static_cast<unsigned long long>(targetCount);
	unsigned long long denominator = static_cast<unsigned long long>(sampleCount) * 2ull;
	std::size_t mapped = static_cast<std::size_t>(scaled / denominator);
	return std::min(mapped, targetCount - 1);
}

std::pair<std::size_t, std::size_t> scaledInterval(std::size_t index, std::size_t count, std::size_t targetCount) noexcept {
	if (count == 0 || targetCount == 0) return std::make_pair(0u, 0u);
	std::size_t start = (index * targetCount) / count;
	std::size_t end = ((index + 1) * targetCount + count - 1) / count;
	if (end <= start) end = std::min(targetCount, start + 1);
	return std::make_pair(std::min(start, targetCount), std::min(end, targetCount));
}

bool ratioCellInRange(int from, int to, int viewportWidth, int cellIndex, int cellCount) noexcept {
	if (from < 0 || to <= 0 || from >= to || viewportWidth <= 0 || cellCount <= 0) return false;
	long long cellLeft = static_cast<long long>(cellIndex) * viewportWidth;
	long long cellRight = static_cast<long long>(cellIndex + 1) * viewportWidth;
	long long cLeft = static_cast<long long>(from) * cellCount;
	long long cRight = static_cast<long long>(to) * cellCount;
	return cellRight > cLeft && cellLeft < cRight;
}

bool miniMapCellHasOverlayBits(std::uint64_t lineBits, int x, bool useBraille) noexcept {
	if (lineBits == 0 || x < 0) return false;
	if (useBraille) {
		const int leftDotColumn = x * 2;
		const int rightDotColumn = leftDotColumn + 1;
		if (leftDotColumn >= 64) return false;
		const std::uint64_t leftBit = (lineBits >> leftDotColumn) & 1ULL;
		const std::uint64_t rightBit = rightDotColumn < 64 ? ((lineBits >> rightDotColumn) & 1ULL) : 0ULL;
		return leftBit != 0 || rightBit != 0;
	}
	return x < 64 && ((lineBits >> x) & 1ULL) != 0;
}

} // namespace

struct MRMiniMapRenderer::Impl {
	struct RenderCache {
		bool valid = false;
		bool braille = true;
		int rowCount = 0;
		int bodyWidth = 0;
		std::size_t documentId = 0;
		std::size_t documentVersion = 0;
		std::size_t totalLines = 1;
		std::size_t windowStartLine = 0;
		std::size_t windowLineCount = 1;
		int viewportWidth = 1;
		std::vector<unsigned char> rowPatterns;
		std::vector<std::size_t> rowLineStarts;
		std::vector<std::size_t> rowLineEnds;
	};

	struct SamplingWindow {
		std::size_t startLine = 0;
		std::size_t lineCount = 1;
	};

	std::uint64_t warmupTaskId = 0;
	std::size_t warmupDocumentId = 0;
	std::size_t warmupVersion = 0;
	int warmupRows = 0;
	int warmupBodyWidth = 0;
	int warmupViewportWidth = 0;
	bool warmupBraille = true;
	std::size_t warmupWindowStartLine = 0;
	std::size_t warmupWindowLineCount = 0;
	RenderCache cache;

	static void normalizeLineMasks(std::vector<OverlayState::LineMask> &masks) {
		if (masks.empty()) return;
		std::sort(masks.begin(), masks.end(), [](const OverlayState::LineMask &lhs, const OverlayState::LineMask &rhs) { return lhs.lineIndex < rhs.lineIndex; });
		std::size_t writeIndex = 0;
		for (std::size_t readIndex = 1; readIndex < masks.size(); ++readIndex) {
			if (masks[writeIndex].lineIndex == masks[readIndex].lineIndex) masks[writeIndex].dotColumnBits |= masks[readIndex].dotColumnBits;
			else
				masks[++writeIndex] = masks[readIndex];
		}
		masks.resize(writeIndex + 1);
	}

	static std::uint64_t lineMaskBits(const std::vector<OverlayState::LineMask> &masks, std::size_t lineIndex) noexcept {
		auto it = std::lower_bound(masks.begin(), masks.end(), lineIndex, [](const OverlayState::LineMask &mask, std::size_t value) { return mask.lineIndex < value; });
		return (it != masks.end() && it->lineIndex == lineIndex) ? it->dotColumnBits : 0;
	}

	static SamplingWindow samplingWindowFor(std::size_t totalLines, std::size_t topLine, int rowCount, bool useBraille) noexcept {
		const std::size_t normalizedTotalLines = std::max<std::size_t>(1, totalLines);
		const std::size_t normalizedRowCount = std::max<std::size_t>(1, static_cast<std::size_t>(std::max(rowCount, 1)));
		const std::size_t samplingRowCount = useBraille ? normalizedRowCount * 4u : normalizedRowCount;
		const std::size_t maxWindowLineCount = normalizedRowCount * 9u;
		SamplingWindow window;
		if (normalizedTotalLines <= maxWindowLineCount) {
			window.startLine = 0;
			window.lineCount = std::max(normalizedTotalLines, samplingRowCount);
			return window;
		}
		window.lineCount = std::max<std::size_t>(1, maxWindowLineCount);
		const std::size_t clampedTop = std::min(topLine, normalizedTotalLines - 1);
		std::size_t preferredStart = 0;
		if (clampedTop > window.lineCount / 2) preferredStart = clampedTop - window.lineCount / 2;
		const std::size_t maxStart = normalizedTotalLines - window.lineCount;
		window.startLine = std::min(preferredStart, maxStart);
		return window;
	}

	bool cacheReadyForViewport(const Viewport &viewport, int rowCount, bool braille, const SamplingWindow &window, std::size_t documentId, std::size_t version) const noexcept {
		return cache.valid && cache.documentId == documentId && cache.documentVersion == version && cache.rowCount == rowCount && cache.bodyWidth == viewport.bodyWidth && cache.viewportWidth == std::max(1, viewport.width) && cache.braille == braille && cache.windowStartLine == window.startLine && cache.windowLineCount == std::max<std::size_t>(1, window.lineCount);
	}

	Signals clearWarmupTask(std::uint64_t expectedTaskId) noexcept {
		Signals signals;

		if (expectedTaskId != 0 && warmupTaskId != expectedTaskId) return signals;
		if (warmupTaskId == 0) return signals;
		warmupTaskId = 0;
		warmupDocumentId = 0;
		warmupVersion = 0;
		warmupRows = 0;
		warmupBodyWidth = 0;
		warmupViewportWidth = 0;
		warmupBraille = true;
		warmupWindowStartLine = 0;
		warmupWindowLineCount = 0;
		signals.notifyTaskStateChanged = true;
		return signals;
	}

	Signals invalidate(bool cancelTask, std::size_t documentId) noexcept {
		Signals signals;
		const bool keepStaleCache = !cancelTask && cache.documentId == documentId && cache.bodyWidth > 0 && cache.rowCount > 0;

		cache.valid = false;
		if (!keepStaleCache) {
			cache.rowPatterns.clear();
			cache.rowLineStarts.clear();
			cache.rowLineEnds.clear();
		}
		if (cancelTask && warmupTaskId != 0) {
			static_cast<void>(mr::coprocessor::globalCoprocessor().cancelTask(warmupTaskId));
			signals.merge(clearWarmupTask(warmupTaskId));
		}
		return signals;
	}
};

MRMiniMapRenderer::MRMiniMapRenderer() noexcept : mImpl(std::make_unique<Impl>()) {
}

MRMiniMapRenderer::~MRMiniMapRenderer() noexcept = default;

bool MRMiniMapRenderer::useBrailleRenderer() noexcept {
	static const int kBrailleWidth = strwidth("\xE2\xA3\xBF");
	return kBrailleWidth == 1;
}

std::string MRMiniMapRenderer::normalizedViewportMarkerGlyph(const std::string &configuredGlyph) {
	if (configuredGlyph.empty() || strwidth(configuredGlyph.c_str()) != 1) return "│";
	return configuredGlyph;
}

std::uint64_t MRMiniMapRenderer::pendingWarmupTaskId() const noexcept {
	return mImpl != nullptr ? mImpl->warmupTaskId : 0;
}

MRMiniMapRenderer::Signals MRMiniMapRenderer::clearWarmupTask(std::uint64_t expectedTaskId) noexcept {
	return mImpl != nullptr ? mImpl->clearWarmupTask(expectedTaskId) : Signals();
}

MRMiniMapRenderer::Signals MRMiniMapRenderer::invalidate(bool cancelTask, std::size_t documentId) noexcept {
	return mImpl != nullptr ? mImpl->invalidate(cancelTask, documentId) : Signals();
}

MRMiniMapRenderer::ApplyWarmupResult MRMiniMapRenderer::applyWarmup(const mr::coprocessor::MiniMapWarmupPayload &payload, std::size_t expectedVersion, std::uint64_t expectedTaskId, std::size_t documentId, std::size_t version) noexcept {
	ApplyWarmupResult result;

	if (mImpl == nullptr) return result;
	if (expectedTaskId == 0 || mImpl->warmupTaskId != expectedTaskId) return result;
	if (documentId != mImpl->warmupDocumentId || version != expectedVersion) return result;
	mImpl->cache.valid = true;
	mImpl->cache.braille = payload.braille;
	mImpl->cache.rowCount = payload.rowCount;
	mImpl->cache.bodyWidth = payload.bodyWidth;
	mImpl->cache.documentId = documentId;
	mImpl->cache.documentVersion = version;
	mImpl->cache.totalLines = std::max<std::size_t>(1, payload.totalLines);
	mImpl->cache.windowStartLine = payload.windowStartLine;
	mImpl->cache.windowLineCount = std::max<std::size_t>(1, payload.windowLineCount);
	mImpl->cache.viewportWidth = std::max(1, payload.viewportWidth);
	mImpl->cache.rowPatterns = payload.rowPatterns;
	mImpl->cache.rowLineStarts = payload.rowLineStarts;
	mImpl->cache.rowLineEnds = payload.rowLineEnds;
	result.signals.merge(mImpl->clearWarmupTask(expectedTaskId));
	result.signals.redraw = true;
	result.applied = true;
	return result;
}

MRMiniMapRenderer::Signals MRMiniMapRenderer::scheduleWarmupIfNeeded(const Viewport &viewport, int rowCount, bool useBraille, std::size_t totalLinesHint, std::size_t topLine, std::size_t documentId, std::size_t version, const mr::editor::ReadSnapshot &snapshot, const MREditSetupSettings &settings) {
	Signals signals;

	if (mImpl == nullptr) return signals;
	if (viewport.bodyWidth <= 0 || rowCount <= 0) return invalidate(true, documentId);
	std::size_t totalLines = std::max<std::size_t>(1, totalLinesHint);
	if (snapshot.exactLineCountKnown()) totalLines = std::max<std::size_t>(1, snapshot.lineCount());
	const Impl::SamplingWindow samplingWindow = Impl::samplingWindowFor(totalLines, topLine, rowCount, useBraille);
	if (mImpl->cacheReadyForViewport(viewport, rowCount, useBraille, samplingWindow, documentId, version)) return signals;
	const int bodyWidth = viewport.bodyWidth;
	const int viewportWidth = std::max(1, viewport.width);
	if (mImpl->warmupTaskId != 0) {
		if (mImpl->warmupDocumentId == documentId && mImpl->warmupVersion == version && mImpl->warmupRows == rowCount && mImpl->warmupBodyWidth == bodyWidth && mImpl->warmupViewportWidth == viewportWidth && mImpl->warmupBraille == useBraille && mImpl->warmupWindowStartLine == samplingWindow.startLine && mImpl->warmupWindowLineCount == samplingWindow.lineCount) return signals;
		static_cast<void>(mr::coprocessor::globalCoprocessor().cancelTask(mImpl->warmupTaskId));
		signals.merge(mImpl->clearWarmupTask(mImpl->warmupTaskId));
	}

	std::uint64_t previousTaskId = mImpl->warmupTaskId;
	mImpl->warmupDocumentId = documentId;
	mImpl->warmupVersion = version;
	mImpl->warmupRows = rowCount;
	mImpl->warmupBodyWidth = bodyWidth;
	mImpl->warmupViewportWidth = viewportWidth;
	mImpl->warmupBraille = useBraille;
	mImpl->warmupWindowStartLine = samplingWindow.startLine;
	mImpl->warmupWindowLineCount = samplingWindow.lineCount;
	mImpl->warmupTaskId = mr::coprocessor::globalCoprocessor().submit(mr::coprocessor::Lane::MiniMap, mr::coprocessor::TaskKind::MiniMapWarmup, documentId, version, "rendering mini map", [snapshot, rowCount, bodyWidth, viewportWidth, useBraille, settings, totalLines, samplingWindow](const mr::coprocessor::TaskInfo &info, std::stop_token stopToken) {
		mr::coprocessor::Result result;
		struct MiniMapLineSample {
			std::uint64_t dotColumnBits = 0;
		};
		std::vector<unsigned char> rowPatterns;
		std::vector<std::size_t> rowLineStarts;
		std::vector<std::size_t> rowLineEnds;
		const int dotRows = useBraille ? std::max(1, rowCount * 4) : std::max(1, rowCount);
		const int dotCols = useBraille ? std::max(1, bodyWidth * 2) : std::max(1, bodyWidth);
		const std::size_t windowStartLine = samplingWindow.startLine;
		const std::size_t windowLineCount = std::max<std::size_t>(1, samplingWindow.lineCount);
		const std::size_t totalMiniMapCells = static_cast<std::size_t>(std::max(1, rowCount)) * static_cast<std::size_t>(std::max(1, bodyWidth));
		std::size_t normalizedTotalLines = std::max<std::size_t>(1, totalLines);
		auto shouldStop = [&]() noexcept { return stopToken.stop_requested() || info.cancelRequested(); };
		result.task = info;

		if (shouldStop()) {
			result.status = mr::coprocessor::TaskStatus::Cancelled;
			return result;
		}
		if (snapshot.exactLineCountKnown()) normalizedTotalLines = std::max<std::size_t>(1, snapshot.lineCount());
		rowPatterns.assign(static_cast<std::size_t>(std::max(0, rowCount) * std::max(0, bodyWidth)), 0);
		rowLineStarts.assign(static_cast<std::size_t>(std::max(0, rowCount)), 0);
		rowLineEnds.assign(static_cast<std::size_t>(std::max(0, rowCount)), 0);
		auto renderRows = [&](int yStart, int yEnd) -> bool {
			mr::editor::ReadSnapshot workerSnapshot = snapshot;
			std::map<std::size_t, MiniMapLineSample> sampledLineSamples;
			auto lineSampleAt = [&](std::size_t lineIndex) -> const MiniMapLineSample & {
				auto cached = sampledLineSamples.find(lineIndex);
				if (cached != sampledLineSamples.end()) return cached->second;
				MiniMapLineSample sample;
				if (lineIndex < normalizedTotalLines) {
					std::size_t lineStart = workerSnapshot.lineStartByIndex(lineIndex);
					std::string lineText = workerSnapshot.lineText(lineStart);
					std::size_t index = 0;
					int visualColumn = 0;
					while (index < lineText.size()) {
						std::size_t current = index;
						std::size_t next = index;
						std::size_t width = 0;
						if (!nextDisplayChar(lineText, next, width, visualColumn, settings)) break;
						unsigned char ch = static_cast<unsigned char>(lineText[current]);
						if (std::isspace(ch) == 0) {
							const long long c = static_cast<long long>(visualColumn);
							const long long w = static_cast<long long>(width);
							const long long n = static_cast<long long>(dotCols);
							const long long v = static_cast<long long>(viewportWidth);
							const int dotColStart = static_cast<int>(c * n / v);
							const int dotColEnd = static_cast<int>(((c + w) * n - 1) / v);
							for (int dc = std::max(0, dotColStart); dc <= std::min(63, dotColEnd); ++dc)
								sample.dotColumnBits |= (1ULL << dc);
						}
						visualColumn += static_cast<int>(width);
						index = next;
					}
				}
				auto inserted = sampledLineSamples.insert(std::make_pair(lineIndex, sample));
				return inserted.first->second;
			};

			for (int y = yStart; y < yEnd; ++y) {
				if (shouldStop()) return false;
				std::pair<std::size_t, std::size_t> lineSpan = scaledInterval(static_cast<std::size_t>(y), static_cast<std::size_t>(rowCount), windowLineCount);
				rowLineStarts[static_cast<std::size_t>(y)] = std::min(normalizedTotalLines, windowStartLine + lineSpan.first);
				rowLineEnds[static_cast<std::size_t>(y)] = std::min(normalizedTotalLines, windowStartLine + lineSpan.second);
				for (int x = 0; x < bodyWidth; ++x) {
					unsigned char pattern = 0;
					if (useBraille) {
						static const unsigned char dotBits[4][2] = {{0x01, 0x08}, {0x02, 0x10}, {0x04, 0x20}, {0x40, 0x80}};
						for (int py = 0; py < 4; ++py) {
							std::size_t sampleRow = static_cast<std::size_t>(y * 4 + py);
							if (sampleRow >= windowLineCount) continue;
							std::size_t lineIndex = windowStartLine + scaledMidpoint(sampleRow, static_cast<std::size_t>(dotRows), windowLineCount);
							const MiniMapLineSample &sample = lineSampleAt(lineIndex);
							for (int px = 0; px < 2; ++px) {
								const int dotColumn = x * 2 + px;
								if (dotColumn < 64 && (sample.dotColumnBits & (1ULL << dotColumn)) != 0) pattern |= dotBits[py][px];
							}
						}
					} else if (static_cast<std::size_t>(y) < windowLineCount) {
						std::size_t lineIndex = windowStartLine + scaledMidpoint(static_cast<std::size_t>(y), static_cast<std::size_t>(rowCount), windowLineCount);
						const MiniMapLineSample &sample = lineSampleAt(lineIndex);
						if (x < 64 && (sample.dotColumnBits & (1ULL << x)) != 0) pattern = 1;
					}
					rowPatterns[static_cast<std::size_t>(y * bodyWidth + x)] = pattern;
				}
			}
			return true;
		};
		const unsigned hardwareWorkers = std::max(1u, std::thread::hardware_concurrency());
		const unsigned workerCount = totalMiniMapCells >= 512 ? std::min<unsigned>(hardwareWorkers, static_cast<unsigned>(std::max(1, rowCount))) : 1u;
		if (workerCount == 1) {
			if (!renderRows(0, rowCount)) {
				result.status = mr::coprocessor::TaskStatus::Cancelled;
				return result;
			}
		} else {
			std::vector<std::future<bool>> workers;

			workers.reserve(workerCount);
			for (unsigned workerIndex = 0; workerIndex < workerCount; ++workerIndex) {
				const int yStart = static_cast<int>((static_cast<std::size_t>(workerIndex) * static_cast<std::size_t>(rowCount)) / static_cast<std::size_t>(workerCount));
				const int yEnd = static_cast<int>((static_cast<std::size_t>(workerIndex + 1) * static_cast<std::size_t>(rowCount)) / static_cast<std::size_t>(workerCount));
				if (yStart >= yEnd) continue;
				workers.push_back(std::async(std::launch::async, [&, yStart, yEnd]() { return renderRows(yStart, yEnd); }));
			}
			for (std::future<bool> &worker : workers)
				if (!worker.get()) {
					result.status = mr::coprocessor::TaskStatus::Cancelled;
					return result;
				}
		}
		result.status = mr::coprocessor::TaskStatus::Completed;
		result.payload = std::make_shared<mr::coprocessor::MiniMapWarmupPayload>(useBraille, rowCount, bodyWidth, normalizedTotalLines, windowStartLine, windowLineCount, viewportWidth, std::move(rowPatterns), std::move(rowLineStarts), std::move(rowLineEnds));
		return result;
	});
	if (mImpl->warmupTaskId != previousTaskId) signals.notifyTaskStateChanged = true;
	return signals;
}

MRMiniMapRenderer::OverlayState MRMiniMapRenderer::computeOverlayState(const mr::editor::ReadSnapshot &snapshot, const mr::editor::Range &selection, const std::vector<mr::editor::Range> &findRanges, const std::vector<mr::editor::Range> &dirtyRanges, std::size_t totalLines, int viewportWidth, int miniMapBodyWidth, bool useBraille, const MREditSetupSettings &settings) const {
	OverlayState overlay;
	const int dotColumns = useBraille ? std::max(1, miniMapBodyWidth * 2) : std::max(1, miniMapBodyWidth);
	const int normalizedViewportWidth = std::max(1, viewportWidth);
	const std::size_t length = snapshot.length();

	if (length == 0 || totalLines == 0 || miniMapBodyWidth <= 0) return overlay;

	auto rangeMaskForLineSlice = [&](std::string_view lineText, std::size_t sliceStart, std::size_t sliceEnd) {
		if (sliceEnd <= sliceStart || sliceStart >= lineText.size() || dotColumns <= 0) return std::uint64_t(0);
		sliceEnd = std::min(sliceEnd, lineText.size());
		std::size_t index = 0;
		int visualColumn = 0;
		std::uint64_t mask = 0;

		while (index < lineText.size()) {
			std::size_t current = index;
			std::size_t next = index;
			std::size_t width = 0;
			if (!nextDisplayChar(TStringView(lineText.data(), lineText.size()), next, width, visualColumn, settings)) break;
			if (next > sliceStart && current < sliceEnd) {
				const int from = visualColumn;
				const int to = visualColumn + static_cast<int>(width);
				for (int dotColumn = 0; dotColumn < std::min(dotColumns, 64); ++dotColumn)
					if (ratioCellInRange(from, to, normalizedViewportWidth, dotColumn, dotColumns)) mask |= (1ULL << dotColumn);
			}
			visualColumn += static_cast<int>(width);
			index = next;
		}
		return mask;
	};

	auto appendRangeMasks = [&](std::vector<OverlayState::LineMask> &target, mr::editor::Range range) {
		range = range.clamped(length);
		if (range.end <= range.start) return;

		for (std::size_t lineStart = snapshot.lineStartByIndex(snapshot.lineIndex(range.start)); lineStart < range.end;) {
			const std::size_t lineIndex = snapshot.lineIndex(lineStart);
			if (lineIndex >= totalLines) break;
			const std::size_t nextLineStart = snapshot.nextLine(lineStart);
			const std::size_t lineEnd = std::min(nextLineStart, length);
			const std::size_t sliceStart = range.start > lineStart ? range.start - lineStart : 0;
			const std::size_t sliceEnd = range.end < lineEnd ? range.end - lineStart : lineEnd - lineStart;
			const std::uint64_t mask = rangeMaskForLineSlice(snapshot.lineText(lineStart), sliceStart, sliceEnd);
			if (mask != 0) target.push_back({lineIndex, mask});
			if (nextLineStart <= lineStart) break;
			lineStart = nextLineStart;
		}
	};

	if (selection.end > selection.start) appendRangeMasks(overlay.findLineMasks, selection.normalized());
	for (const mr::editor::Range &range : findRanges)
		appendRangeMasks(overlay.findLineMasks, range);
	for (const mr::editor::Range &range : dirtyRanges)
		appendRangeMasks(overlay.dirtyLineMasks, range);
	Impl::normalizeLineMasks(overlay.findLineMasks);
	Impl::normalizeLineMasks(overlay.dirtyLineMasks);
	return overlay;
}

void MRMiniMapRenderer::drawGutter(TDrawBuffer &buffer, int y, int miniMapRows, int viewWidth, const Viewport &viewport, std::size_t totalLines, std::size_t topLine, bool useBraille, const std::string &viewportMarkerGlyph, const Palette &palette, const OverlayState &overlay) const {
	if (mImpl == nullptr) return;
	if (viewport.bodyWidth <= 0 || viewport.bodyX < 0 || viewport.infoX < 0 || totalLines == 0 || miniMapRows <= 0) return;

	const std::array<std::string, 256> &glyphTable = brailleGlyphTable();
	const int bodyX = viewport.bodyX;
	const int bodyWidth = viewport.bodyWidth;
	const Impl::SamplingWindow samplingWindow = Impl::samplingWindowFor(totalLines, topLine, miniMapRows, useBraille);
	const bool cacheReady = mImpl->cacheReadyForViewport(viewport, miniMapRows, useBraille, samplingWindow, mImpl->cache.documentId, mImpl->cache.documentVersion);
	const bool stalePatternCacheUsable = !cacheReady && mImpl->cache.bodyWidth == bodyWidth && mImpl->cache.rowCount == miniMapRows && !mImpl->cache.rowPatterns.empty();
	std::size_t rowLineStart = 0;
	std::size_t rowLineEnd = 0;

	if (y >= miniMapRows) {
		buffer.moveChar(static_cast<ushort>(bodyX), ' ', palette.normal, static_cast<ushort>(bodyWidth));
		if (viewport.separatorX >= 0 && viewport.separatorX < viewWidth) buffer.moveChar(static_cast<ushort>(viewport.separatorX), ' ', palette.normal, 1);
		buffer.moveChar(static_cast<ushort>(viewport.infoX), ' ', palette.normal, 1);
		return;
	}

	if ((cacheReady || stalePatternCacheUsable) && static_cast<std::size_t>(y) < mImpl->cache.rowLineStarts.size() && static_cast<std::size_t>(y) < mImpl->cache.rowLineEnds.size()) {
		rowLineStart = mImpl->cache.rowLineStarts[static_cast<std::size_t>(y)];
		rowLineEnd = mImpl->cache.rowLineEnds[static_cast<std::size_t>(y)];
	} else {
		std::pair<std::size_t, std::size_t> rowSpan = scaledInterval(static_cast<std::size_t>(y), static_cast<std::size_t>(std::max(miniMapRows, 1)), samplingWindow.lineCount);
		const std::size_t normTotal = std::max<std::size_t>(1, totalLines);
		rowLineStart = std::min(samplingWindow.startLine + rowSpan.first, normTotal);
		rowLineEnd = std::min(samplingWindow.startLine + rowSpan.second, normTotal);
	}

	for (int x = 0; x < bodyWidth; ++x) {
		unsigned char pattern = 0;
		if (cacheReady || stalePatternCacheUsable) {
			std::size_t index = static_cast<std::size_t>(y * bodyWidth + x);
			if (index < mImpl->cache.rowPatterns.size()) pattern = mImpl->cache.rowPatterns[index];
		}
		bool cellFind = false;
		bool cellChanged = false;
		bool cellError = false;
		if (useBraille) {
			for (int py = 0; py < 4 && (!cellFind || !cellChanged); ++py) {
				std::size_t sampleRow = static_cast<std::size_t>(y * 4 + py);
				if (sampleRow >= samplingWindow.lineCount) continue;
				std::size_t lineIndex = samplingWindow.startLine + scaledMidpoint(sampleRow, static_cast<std::size_t>(std::max(miniMapRows * 4, 1)), samplingWindow.lineCount);
				const std::uint64_t findBits = Impl::lineMaskBits(overlay.findLineMasks, lineIndex);
				const std::uint64_t dirtyBits = Impl::lineMaskBits(overlay.dirtyLineMasks, lineIndex);
				if (!cellFind && miniMapCellHasOverlayBits(findBits, x, true)) cellFind = true;
				if (!cellChanged && miniMapCellHasOverlayBits(dirtyBits, x, true)) cellChanged = true;
			}
		} else {
			std::size_t lineIndex = samplingWindow.startLine + scaledMidpoint(static_cast<std::size_t>(y), static_cast<std::size_t>(std::max(miniMapRows, 1)), samplingWindow.lineCount);
			const std::uint64_t findBits = Impl::lineMaskBits(overlay.findLineMasks, lineIndex);
			const std::uint64_t dirtyBits = Impl::lineMaskBits(overlay.dirtyLineMasks, lineIndex);
			cellFind = miniMapCellHasOverlayBits(findBits, x, false);
			cellChanged = miniMapCellHasOverlayBits(dirtyBits, x, false);
		}
		TColorAttr rowPriorityColor = palette.normal;
		if (cellFind) rowPriorityColor = palette.findMarker;
		else if (cellError)
			rowPriorityColor = palette.errorMarker;
		else if (cellChanged)
			rowPriorityColor = palette.changed;
		const bool cellOverlayActive = cellFind || cellError || cellChanged;
		TColorAttr cellColor = (pattern != 0 || cellOverlayActive) ? rowPriorityColor : palette.normal;
		if (useBraille) buffer.moveStr(static_cast<ushort>(bodyX + x), glyphTable[pattern], cellColor, 1);
		else if (pattern != 0)
			buffer.moveStr(static_cast<ushort>(bodyX + x), "\xE2\x96\x88", cellColor, 1);
		else
			buffer.moveChar(static_cast<ushort>(bodyX + x), ' ', cellColor, 1);
	}

	if (viewport.separatorX >= 0 && viewport.separatorX < viewWidth) buffer.moveChar(static_cast<ushort>(viewport.separatorX), ' ', palette.normal, 1);

	std::size_t clampedTopLine = std::min(topLine, totalLines - 1);
	std::size_t visibleLines = static_cast<std::size_t>(std::max(miniMapRows, 1));
	std::size_t viewportLineEnd = std::min(totalLines, clampedTopLine + visibleLines);
	bool markerVisible = false;
	if (rowLineEnd > rowLineStart) markerVisible = rowLineStart < viewportLineEnd && rowLineEnd > clampedTopLine;
	if (markerVisible) buffer.moveStr(static_cast<ushort>(viewport.infoX), viewportMarkerGlyph, palette.viewport, 1);
	else
		buffer.moveChar(static_cast<ushort>(viewport.infoX), ' ', palette.normal, 1);
}
#include "MRTreeSitterDocument.hpp"

#include <algorithm>
#include <cstdint>
#include <new>
#include <string>
#include <utility>

#include <tree_sitter/api.h>

#include "../../app/utils/MRStringUtils.hpp"
#include "../../piecetable/MRTextDocument.hpp"
#include "../MRSyntax.hpp"

extern "C" const TSLanguage *tree_sitter_c(void);
extern "C" const TSLanguage *tree_sitter_cpp(void);
extern "C" const TSLanguage *tree_sitter_javascript(void);
extern "C" const TSLanguage *tree_sitter_python(void);
extern "C" const TSLanguage *tree_sitter_json(void);
extern "C" const TSLanguage *tree_sitter_mrmac(void);

namespace {

bool isIndentWhitespace(char ch) noexcept {
	return ch == ' ' || ch == '\t';
}

void stripLeadingUtf8Bom(std::string &text) {
	if (text.size() >= 3 && static_cast<unsigned char>(text[0]) == 0xEFu && static_cast<unsigned char>(text[1]) == 0xBBu && static_cast<unsigned char>(text[2]) == 0xBFu)
		text.erase(0, 3);
}

std::string normalizedIndentLineText(const mr::editor::ReadSnapshot &snapshot, std::size_t cursorOffset) {
	std::string lineText = snapshot.lineText(snapshot.lineStart(cursorOffset));

	stripLeadingUtf8Bom(lineText);
	return upperAscii(trimAscii(lineText));
}

MRTreeSitterDocument::Language configuredTreeSitterLanguage(std::string_view configuredLanguage) noexcept {
	const std::string normalized = upperAscii(trimAscii(std::string(configuredLanguage)));

	if (normalized == "C") return MRTreeSitterDocument::Language::C;
	if (normalized == "CPP") return MRTreeSitterDocument::Language::Cpp;
	if (normalized == "JAVASCRIPT") return MRTreeSitterDocument::Language::JavaScript;
	if (normalized == "PYTHON") return MRTreeSitterDocument::Language::Python;
	if (normalized == "JSON") return MRTreeSitterDocument::Language::Json;
	if (normalized == "MRMAC") return MRTreeSitterDocument::Language::MRMAC;
	return MRTreeSitterDocument::Language::None;
}

const TSLanguage *treeSitterParserLanguage(MRTreeSitterDocument::Language language) noexcept {
	switch (language) {
		case MRTreeSitterDocument::Language::C:
			return tree_sitter_c();
		case MRTreeSitterDocument::Language::Cpp:
			return tree_sitter_cpp();
		case MRTreeSitterDocument::Language::JavaScript:
			return tree_sitter_javascript();
		case MRTreeSitterDocument::Language::Python:
			return tree_sitter_python();
		case MRTreeSitterDocument::Language::Json:
			return tree_sitter_json();
		case MRTreeSitterDocument::Language::MRMAC:
			return tree_sitter_mrmac();
		case MRTreeSitterDocument::Language::None:
			break;
	}
	return nullptr;
}

bool isTreeSitterCommentOrLiteral(const char *typeName) noexcept {
	if (typeName == nullptr || *typeName == '\0') return false;
	const std::string_view type(typeName);
	return type.find("comment") != std::string_view::npos || type.find("string") != std::string_view::npos || type.find("char_literal") != std::string_view::npos;
}

std::size_t previousNonWhitespaceOnLine(const mr::editor::ReadSnapshot &snapshot, std::size_t cursorOffset) noexcept {
	const std::size_t safeOffset = std::min(cursorOffset, snapshot.length());
	const std::size_t lineStart = snapshot.lineStart(safeOffset);
	std::size_t probe = safeOffset;

	while (probe > lineStart) {
		const std::size_t previous = probe - 1;
		if (!isIndentWhitespace(snapshot.charAt(previous))) return previous;
		probe = previous;
	}
	return snapshot.length();
}

std::size_t firstNonWhitespaceOnLine(const mr::editor::ReadSnapshot &snapshot, std::size_t cursorOffset) noexcept {
	const std::size_t safeOffset = std::min(cursorOffset, snapshot.length());
	const std::size_t lineStart = snapshot.lineStart(safeOffset);
	const std::size_t lineEnd = snapshot.lineEnd(safeOffset);
	std::size_t probe = lineStart;

	while (probe < lineEnd) {
		if (!isIndentWhitespace(snapshot.charAt(probe))) return probe;
		probe = std::min(lineEnd, probe + 1);
	}
	return snapshot.length();
}

bool isCommentOrLiteralAtOffset(const TSTree *tree, std::size_t offset) noexcept {
	if (tree == nullptr) return false;
	TSNode node = ts_node_descendant_for_byte_range(ts_tree_root_node(tree), static_cast<uint32_t>(std::min<std::size_t>(offset, UINT32_MAX)),
													static_cast<uint32_t>(std::min<std::size_t>(offset + 1, UINT32_MAX)));
	while (!ts_node_is_null(node)) {
		const char *typeName = ts_node_type(node);
		if (isTreeSitterCommentOrLiteral(typeName)) return true;
		node = ts_node_parent(node);
	}
	return false;
}

bool shouldIncreaseMrmacIndent(const mr::editor::ReadSnapshot &snapshot, const TSTree *tree, std::size_t cursorOffset) noexcept {
	const std::size_t previousOffset = previousNonWhitespaceOnLine(snapshot, cursorOffset);

	if (tree == nullptr || previousOffset >= snapshot.length()) return false;
	if (isCommentOrLiteralAtOffset(tree, previousOffset)) return false;

	const std::string lineText = normalizedIndentLineText(snapshot, cursorOffset);
	if (lineText.empty()) return false;
	if (lineText == "ELSE") return true;
	if (lineText.starts_with("$MACRO") && lineText.back() == ';') return true;
	if (lineText.starts_with("IF ") && lineText.ends_with("THEN")) return true;
	if (lineText.starts_with("WHILE ") && lineText.ends_with("DO")) return true;
	return false;
}

bool shouldIncreasePythonIndent(const mr::editor::ReadSnapshot &snapshot, const TSTree *tree, std::size_t cursorOffset) noexcept {
	const std::size_t previousOffset = previousNonWhitespaceOnLine(snapshot, cursorOffset);

	if (tree == nullptr || previousOffset >= snapshot.length()) return false;
	if (snapshot.charAt(previousOffset) != ':') return false;
	if (isCommentOrLiteralAtOffset(tree, previousOffset)) return false;

	const std::string lineText = normalizedIndentLineText(snapshot, cursorOffset);
	if (lineText.empty() || !lineText.ends_with(":")) return false;
	if (lineText == "ELSE:" || lineText == "TRY:" || lineText == "FINALLY:") return true;
	if (lineText.starts_with("IF ") || lineText.starts_with("ELIF ") || lineText.starts_with("FOR ") || lineText.starts_with("WHILE ") || lineText.starts_with("WITH ") ||
		lineText.starts_with("MATCH ") || lineText.starts_with("CASE ") || lineText.starts_with("EXCEPT ") || lineText.starts_with("DEF ") || lineText.starts_with("CLASS "))
		return true;
	if (lineText.starts_with("ASYNC DEF ") || lineText.starts_with("ASYNC FOR ") || lineText.starts_with("ASYNC WITH ")) return true;
	return false;
}

bool shouldDedentMrmacLine(const mr::editor::ReadSnapshot &snapshot, const TSTree *tree, std::size_t cursorOffset) noexcept {
	const std::size_t firstOffset = firstNonWhitespaceOnLine(snapshot, cursorOffset);

	if (tree == nullptr || firstOffset >= snapshot.length()) return false;
	if (isCommentOrLiteralAtOffset(tree, firstOffset)) return false;
	return normalizedIndentLineText(snapshot, cursorOffset) == "ELSE";
}

bool shouldDedentPythonLine(const mr::editor::ReadSnapshot &snapshot, const TSTree *tree, std::size_t cursorOffset) noexcept {
	const std::size_t firstOffset = firstNonWhitespaceOnLine(snapshot, cursorOffset);
	const std::string lineText = normalizedIndentLineText(snapshot, cursorOffset);

	if (tree == nullptr || firstOffset >= snapshot.length()) return false;
	if (lineText.empty() || !lineText.ends_with(":")) return false;
	if (isCommentOrLiteralAtOffset(tree, firstOffset)) return false;
	if (lineText == "ELSE:" || lineText == "FINALLY:") return true;
	if (lineText.starts_with("ELIF ") || lineText.starts_with("CASE ")) return true;
	if (lineText == "EXCEPT:" || lineText.starts_with("EXCEPT ")) return true;
	return false;
}

bool shouldDedentBracketLine(const mr::editor::ReadSnapshot &snapshot, const TSTree *tree, std::size_t cursorOffset) noexcept {
	const std::size_t firstOffset = firstNonWhitespaceOnLine(snapshot, cursorOffset);
	const std::string lineText = trimAscii(snapshot.lineText(snapshot.lineStart(cursorOffset)));

	if (tree == nullptr || firstOffset >= snapshot.length() || lineText.empty()) return false;
	if (isCommentOrLiteralAtOffset(tree, firstOffset)) return false;
	return lineText.starts_with("}") || lineText.starts_with("]") || lineText.starts_with(")");
}

struct TreeSitterSnapshotInput {
	mr::editor::ReadSnapshot snapshot;
	std::size_t pieceIndex = 0;
	std::size_t pieceStart = 0;
	std::size_t pieceEnd = 0;
	mr::editor::PieceChunkView piece;
	bool pieceValid = false;
};

const char *readTreeSitterSnapshot(void *payload, uint32_t byteIndex, TSPoint, uint32_t *bytesRead) {
	TreeSitterSnapshotInput &input = *static_cast<TreeSitterSnapshotInput *>(payload);
	std::size_t pieceCount = input.snapshot.pieceCount();
	std::size_t target = static_cast<std::size_t>(byteIndex);
	std::size_t scanIndex = 0;
	std::size_t scanOffset = 0;

	*bytesRead = 0;
	if (target >= input.snapshot.length()) return nullptr;
	if (input.pieceValid && target >= input.pieceStart && target < input.pieceEnd) {
		const std::size_t chunkOffset = target - input.pieceStart;
		const std::size_t available = input.piece.length - chunkOffset;
		*bytesRead = static_cast<uint32_t>(std::min<std::size_t>(available, UINT32_MAX));
		return input.piece.data + chunkOffset;
	}
	if (input.pieceValid && target >= input.pieceEnd) {
		scanIndex = input.pieceIndex + 1;
		scanOffset = input.pieceEnd;
	}
	input.pieceValid = false;
	for (std::size_t i = scanIndex; i < pieceCount; ++i) {
		const mr::editor::PieceChunkView nextPiece = input.snapshot.pieceChunk(i);
		if (nextPiece.length == 0) continue;
		if (target < scanOffset + nextPiece.length) {
			input.pieceIndex = i;
			input.pieceStart = scanOffset;
			input.pieceEnd = scanOffset + nextPiece.length;
			input.piece = nextPiece;
			input.pieceValid = true;
			break;
		}
		scanOffset += nextPiece.length;
	}
	if (!input.pieceValid) return nullptr;
	const std::size_t chunkOffset = target - input.pieceStart;
	const std::size_t available = input.piece.length - chunkOffset;
	*bytesRead = static_cast<uint32_t>(std::min<std::size_t>(available, UINT32_MAX));
	return input.piece.data + chunkOffset;
}

} // namespace

struct MRTreeSitterDocument::Impl {
	struct Point {
		std::uint32_t row = 0;
		std::uint32_t column = 0;
	};

	struct PendingEdit {
		bool valid = false;
		std::size_t startByte = 0;
		std::size_t oldEndByte = 0;
		std::size_t newEndByte = 0;
		Point startPoint;
		Point oldEndPoint;
		Point newEndPoint;
	};

	Language language = Language::None;
	PendingEdit pendingEdit;
	TSParser *parser = nullptr;
	TSTree *tree = nullptr;
	std::size_t documentId = 0;
	std::size_t version = 0;

	static Point pointAt(const mr::editor::TextDocument &document, std::size_t offset) noexcept {
		Point point;

		offset = std::min(offset, document.length());
		point.row = static_cast<std::uint32_t>(std::min<std::size_t>(document.lineIndex(offset), UINT32_MAX));
		point.column = static_cast<std::uint32_t>(std::min<std::size_t>(document.column(offset), UINT32_MAX));
		return point;
	}

	void clearTree() noexcept {
		if (tree != nullptr) {
			ts_tree_delete(tree);
			tree = nullptr;
		}
		documentId = 0;
		version = 0;
	}

	void releaseParser() noexcept {
		if (parser != nullptr) {
			ts_parser_delete(parser);
			parser = nullptr;
		}
	}

	const TSLanguage *parserLanguage() const noexcept {
		return treeSitterParserLanguage(language);
	}
};

MRTreeSitterDocument::MRTreeSitterDocument() noexcept : mImpl(new (std::nothrow) Impl()) {
}

MRTreeSitterDocument::~MRTreeSitterDocument() noexcept = default;

void MRTreeSitterDocument::clear() noexcept {
	if (mImpl == nullptr) return;
	mImpl->pendingEdit = Impl::PendingEdit();
	mImpl->clearTree();
	mImpl->releaseParser();
	mImpl->language = Language::None;
}

void MRTreeSitterDocument::setLanguageContext(std::string_view path, std::string_view title, std::string_view configuredLanguage) noexcept {
	if (mImpl == nullptr) return;
	Language nextLanguage = configuredTreeSitterLanguage(configuredLanguage);

	if (nextLanguage == Language::None) nextLanguage = configuredTreeSitterLanguage(tmrDetectTreeSitterLanguageName(std::string(path), std::string(title)));

	if (nextLanguage == mImpl->language) return;
	mImpl->pendingEdit = Impl::PendingEdit();
	mImpl->clearTree();
	if (nextLanguage == Language::None) mImpl->releaseParser();
	mImpl->language = nextLanguage;
}

void MRTreeSitterDocument::prepareDocumentAdoption(const mr::editor::TextDocument &currentDocument, const mr::editor::TextDocument &nextDocument, const mr::editor::DocumentChangeSet *changeSet) noexcept {
	if (mImpl == nullptr) return;
	mImpl->pendingEdit = Impl::PendingEdit();
	if (changeSet == nullptr || !changeSet->changed) return;
	if (currentDocument.documentId() != nextDocument.documentId()) return;
	const mr::editor::Range touched = changeSet->touchedRange.normalized();
	const std::size_t start = std::min<std::size_t>(touched.start, changeSet->oldLength);
	const long long delta = static_cast<long long>(changeSet->newLength) - static_cast<long long>(changeSet->oldLength);
	std::size_t oldEnd = touched.end;
	std::size_t newEnd = touched.end;

	if (delta >= 0) oldEnd = oldEnd >= static_cast<std::size_t>(delta) ? oldEnd - static_cast<std::size_t>(delta) : start;
	else
		newEnd = newEnd >= static_cast<std::size_t>(-delta) ? newEnd - static_cast<std::size_t>(-delta) : start;
	oldEnd = std::clamp(oldEnd, start, changeSet->oldLength);
	newEnd = std::clamp(newEnd, start, changeSet->newLength);
	mImpl->pendingEdit.valid = true;
	mImpl->pendingEdit.startByte = start;
	mImpl->pendingEdit.oldEndByte = oldEnd;
	mImpl->pendingEdit.newEndByte = newEnd;
	mImpl->pendingEdit.startPoint = Impl::pointAt(currentDocument, start);
	mImpl->pendingEdit.oldEndPoint = Impl::pointAt(currentDocument, oldEnd);
	mImpl->pendingEdit.newEndPoint = Impl::pointAt(nextDocument, newEnd);
}

bool MRTreeSitterDocument::syncToDocument(const mr::editor::ReadSnapshot &snapshot, std::size_t documentId, std::size_t version) noexcept {
	if (mImpl == nullptr) return false;
	if (mImpl->language == Language::None) {
		mImpl->pendingEdit = Impl::PendingEdit();
		mImpl->clearTree();
		mImpl->releaseParser();
		return false;
	}
	if (mImpl->tree != nullptr && mImpl->documentId == documentId && mImpl->version == version && !mImpl->pendingEdit.valid) return true;
	const TSLanguage *nextLanguage = mImpl->parserLanguage();

	if (nextLanguage == nullptr) {
		mImpl->pendingEdit = Impl::PendingEdit();
		mImpl->clearTree();
		return false;
	}
	if (mImpl->parser == nullptr) mImpl->parser = ts_parser_new();
	if (mImpl->parser == nullptr) {
		mImpl->pendingEdit = Impl::PendingEdit();
		mImpl->clearTree();
		return false;
	}
	if (ts_parser_language(mImpl->parser) != nextLanguage && !ts_parser_set_language(mImpl->parser, nextLanguage)) {
		mImpl->pendingEdit = Impl::PendingEdit();
		mImpl->clearTree();
		mImpl->releaseParser();
		return false;
	}
	const bool reuseTree = mImpl->tree != nullptr && mImpl->documentId == documentId && mImpl->pendingEdit.valid;
	TSTree *previousTree = mImpl->tree;
	TSTree *parsedTree = nullptr;

	if (reuseTree) {
		TSInputEdit edit;

		edit.start_byte = static_cast<uint32_t>(std::min<std::size_t>(mImpl->pendingEdit.startByte, UINT32_MAX));
		edit.old_end_byte = static_cast<uint32_t>(std::min<std::size_t>(mImpl->pendingEdit.oldEndByte, UINT32_MAX));
		edit.new_end_byte = static_cast<uint32_t>(std::min<std::size_t>(mImpl->pendingEdit.newEndByte, UINT32_MAX));
		edit.start_point = TSPoint{mImpl->pendingEdit.startPoint.row, mImpl->pendingEdit.startPoint.column};
		edit.old_end_point = TSPoint{mImpl->pendingEdit.oldEndPoint.row, mImpl->pendingEdit.oldEndPoint.column};
		edit.new_end_point = TSPoint{mImpl->pendingEdit.newEndPoint.row, mImpl->pendingEdit.newEndPoint.column};
		ts_tree_edit(previousTree, &edit);
	}
	{
		TreeSitterSnapshotInput input;
		TSInput source;

		input.snapshot = snapshot;
		source.payload = &input;
		source.read = readTreeSitterSnapshot;
		source.encoding = TSInputEncodingUTF8;
		source.decode = nullptr;
		parsedTree = ts_parser_parse(mImpl->parser, reuseTree ? previousTree : nullptr, source);
	}
	mImpl->pendingEdit = Impl::PendingEdit();
	if (parsedTree == nullptr) {
		mImpl->clearTree();
		return false;
	}
	if (previousTree != nullptr) ts_tree_delete(previousTree);
	mImpl->tree = parsedTree;
	mImpl->documentId = documentId;
	mImpl->version = version;
	return true;
}

bool MRTreeSitterDocument::shouldIncreaseIndentOnNewLine(const mr::editor::ReadSnapshot &snapshot, std::size_t cursorOffset) const noexcept {
	if (mImpl == nullptr || mImpl->tree == nullptr) return false;
	if (mImpl->language == Language::MRMAC) return shouldIncreaseMrmacIndent(snapshot, mImpl->tree, cursorOffset);
	if (mImpl->language == Language::Python) return shouldIncreasePythonIndent(snapshot, mImpl->tree, cursorOffset);
	const std::size_t previousOffset = previousNonWhitespaceOnLine(snapshot, cursorOffset);
	if (previousOffset >= snapshot.length()) return false;
	const char previousChar = snapshot.charAt(previousOffset);
	if (previousChar != '{' && previousChar != '(' && previousChar != '[') return false;
	return !isCommentOrLiteralAtOffset(mImpl->tree, previousOffset);
}

bool MRTreeSitterDocument::shouldDedentCurrentLine(const mr::editor::ReadSnapshot &snapshot, std::size_t cursorOffset) const noexcept {
	if (mImpl == nullptr || mImpl->tree == nullptr) return false;
	switch (mImpl->language) {
		case Language::MRMAC:
			return shouldDedentMrmacLine(snapshot, mImpl->tree, cursorOffset);
		case Language::Python:
			return shouldDedentPythonLine(snapshot, mImpl->tree, cursorOffset);
		case Language::C:
		case Language::Cpp:
		case Language::JavaScript:
		case Language::Json:
			return shouldDedentBracketLine(snapshot, mImpl->tree, cursorOffset);
		case Language::None:
			break;
	}
	return false;
}

std::vector<MRSyntaxTokenMap> MRTreeSitterDocument::buildTokenMapsForSnapshotLines(Language language, const mr::editor::ReadSnapshot &snapshot, const std::vector<std::size_t> &lineStarts) {
	std::vector<MRSyntaxTokenMap> tokenMaps;
	const TSLanguage *parserLanguage = treeSitterParserLanguage(language);
	TSParser *parser = nullptr;
	TSTree *tree = nullptr;

	tokenMaps.reserve(lineStarts.size());
	for (std::size_t i = 0; i < lineStarts.size(); ++i) tokenMaps.push_back(MRSyntaxTokenMap(snapshot.lineText(lineStarts[i]).size(), MRSyntaxToken::Text));
	if (lineStarts.empty()) return tokenMaps;
	if (parserLanguage == nullptr) return tokenMaps;

	parser = ts_parser_new();
	if (parser == nullptr) return tokenMaps;
	if (!ts_parser_set_language(parser, parserLanguage)) {
		ts_parser_delete(parser);
		return tokenMaps;
	}
	{
		TreeSitterSnapshotInput input;
		TSInput source;

		input.snapshot = snapshot;
		source.payload = &input;
		source.read = readTreeSitterSnapshot;
		source.encoding = TSInputEncodingUTF8;
		source.decode = nullptr;
		tree = ts_parser_parse(parser, nullptr, source);
	}
	ts_parser_delete(parser);
	if (tree == nullptr) return tokenMaps;

	TSNode root = ts_tree_root_node(tree);
	for (std::size_t lineIndex = 0; lineIndex < lineStarts.size(); ++lineIndex) {
		const std::size_t safeLineStart = std::min(lineStarts[lineIndex], snapshot.length());
		const std::size_t lineEnd = safeLineStart + tokenMaps[lineIndex].size();
		std::vector<TSNode> stack;

		if (tokenMaps[lineIndex].empty()) continue;
		stack.push_back(root);
		while (!stack.empty()) {
			const TSNode node = stack.back();
			stack.pop_back();

			if (ts_node_is_null(node)) continue;
			const std::size_t nodeStart = ts_node_start_byte(node);
			const std::size_t nodeEnd = ts_node_end_byte(node);
			if (nodeEnd <= safeLineStart || nodeStart >= lineEnd || nodeEnd <= nodeStart) continue;

			const uint32_t childCount = ts_node_child_count(node);
			for (uint32_t childIndex = childCount; childIndex > 0; --childIndex) stack.push_back(ts_node_child(node, childIndex - 1));

			const char *typeName = ts_node_type(node);
			if (typeName == nullptr || *typeName == '\0') continue;
			const std::string_view type(typeName);
			MRSyntaxToken token = MRSyntaxToken::Text;
			TSNode parent = ts_node_parent(node);
			const char *parentTypeName = !ts_node_is_null(parent) ? ts_node_type(parent) : nullptr;
			const std::string_view parentType = parentTypeName != nullptr ? std::string_view(parentTypeName) : std::string_view();

			if (parentType == "pair" && (type == "string" || type == "property_identifier" || type == "shorthand_property_identifier")) token = MRSyntaxToken::Key;
			if (token == MRSyntaxToken::Text) {
				if (type.find("comment") != std::string_view::npos) token = MRSyntaxToken::Comment;
				else if (type.find("preproc") != std::string_view::npos || type.find("directive") != std::string_view::npos || type == "hash_bang_line")
					token = MRSyntaxToken::Directive;
				else if (type.find("string") != std::string_view::npos || type.find("char_literal") != std::string_view::npos || type == "escape_sequence")
					token = MRSyntaxToken::String;
				else if (type.find("number") != std::string_view::npos || type.find("integer") != std::string_view::npos || type.find("float") != std::string_view::npos)
					token = MRSyntaxToken::Number;
				else {
					switch (language) {
						case Language::C:
							if (type == "true" || type == "false" || type == "null")
								token = MRSyntaxToken::Keyword;
							else if (type == "primitive_type" || type == "type_identifier" || type == "sized_type_specifier")
								token = MRSyntaxToken::Type;
							else if (type == "storage_class_specifier" || type == "type_qualifier")
								token = MRSyntaxToken::Keyword;
							else if (type == "if" || type == "else" || type == "for" || type == "while" || type == "do" || type == "switch" || type == "case" || type == "default" ||
									 type == "break" || type == "continue" || type == "return" || type == "goto" || type == "sizeof" || type == "typedef" || type == "struct" ||
									 type == "union" || type == "enum" || type == "static" || type == "extern" || type == "inline" || type == "const" || type == "volatile")
								token = MRSyntaxToken::Keyword;
							break;
						case Language::Cpp:
							if (type == "true" || type == "false" || type == "null" || type == "nullptr")
								token = MRSyntaxToken::Keyword;
							else if (type == "primitive_type" || type == "type_identifier" || type == "sized_type_specifier" || type == "namespace_identifier" ||
									 type == "auto" || type == "template_type" ||
									 (type == "qualified_identifier" &&
									  (parentType == "base_class_clause" || parentType == "class_specifier" || parentType == "struct_specifier" || parentType == "union_specifier" ||
									   parentType == "type_requirement" || parentType == "compound_literal_expression")))
								token = MRSyntaxToken::Type;
							else if (type == "storage_class_specifier" || type == "type_qualifier" || type == "this")
								token = MRSyntaxToken::Keyword;
							else if (type == "if" || type == "else" || type == "for" || type == "while" || type == "do" || type == "switch" || type == "case" || type == "default" ||
									 type == "break" || type == "continue" || type == "return" || type == "goto" || type == "try" || type == "catch" || type == "throw" ||
									 type == "new" || type == "delete" || type == "void" || type == "typedef" || type == "struct" || type == "union" || type == "enum" ||
									 type == "namespace" || type == "template" || type == "typename" || type == "using" || type == "public" || type == "private" ||
									 type == "protected" || type == "virtual" || type == "override" || type == "constexpr" || type == "consteval" || type == "constinit" ||
									 type == "explicit" || type == "final" ||
									 type == "inline" || type == "static" || type == "extern" || type == "volatile" || type == "mutable" || type == "friend" ||
									 type == "operator" || type == "noexcept" || type == "requires" || type == "concept" || type == "sizeof" || type == "co_await" ||
									 type == "co_return" || type == "co_yield")
								token = MRSyntaxToken::Keyword;
							break;
						case Language::JavaScript:
							if (type == "true" || type == "false" || type == "null")
								token = MRSyntaxToken::Keyword;
							else if (type == "undefined" || type == "null")
								token = MRSyntaxToken::Type;
							else if (type == "this" || type == "super")
								token = MRSyntaxToken::Keyword;
							else if (type == "if" || type == "else" || type == "for" || type == "while" || type == "do" || type == "switch" || type == "case" || type == "default" ||
									 type == "break" || type == "continue" || type == "return" || type == "try" || type == "catch" || type == "throw" || type == "finally" ||
									 type == "import" || type == "export" || type == "from" || type == "as" || type == "function" || type == "class" || type == "new" ||
									 type == "delete" || type == "typeof" || type == "instanceof" || type == "yield" || type == "await" || type == "async" || type == "const" ||
									 type == "let" || type == "var" || type == "extends" || type == "of" || type == "static" || type == "void" || type == "debugger" ||
									 type == "with" || type == "get" || type == "set")
								token = MRSyntaxToken::Keyword;
							break;
						case Language::Python:
							if (type == "true" || type == "false" || type == "none")
								token = MRSyntaxToken::Keyword;
							else if (type == "identifier" && parentType == "type")
								token = MRSyntaxToken::Type;
							else if (type == "if" || type == "elif" || type == "else" || type == "for" || type == "while" || type == "break" || type == "continue" ||
									 type == "return" || type == "try" || type == "except" || type == "finally" || type == "raise" || type == "import" || type == "from" ||
									 type == "as" || type == "def" || type == "class" || type == "lambda" || type == "yield" || type == "await" || type == "async" ||
									 type == "with" || type == "pass" || type == "assert" || type == "match" || type == "case" || type == "global" || type == "nonlocal" ||
									 type == "del" || type == "and" || type == "or" || type == "not" || type == "in" || type == "is" || type == "exec" || type == "print")
								token = MRSyntaxToken::Keyword;
							break;
						case Language::Json:
							if (type == "true" || type == "false" || type == "null")
								token = MRSyntaxToken::Keyword;
							break;
						case Language::MRMAC:
							if (type == "directive" || type == "keyspec")
								token = MRSyntaxToken::Directive;
							else if (type == "keyword")
								token = MRSyntaxToken::Keyword;
							else if (type == "string_literal")
								token = MRSyntaxToken::String;
							else if (type == "integer_literal")
								token = MRSyntaxToken::Number;
							break;
						case Language::None:
							break;
					}
				}
			}
			if (token == MRSyntaxToken::Text) continue;

			const std::size_t paintStart = std::max(nodeStart, safeLineStart) - safeLineStart;
			const std::size_t paintEnd = std::min(nodeEnd, lineEnd) - safeLineStart;
			for (std::size_t index = paintStart; index < paintEnd && index < tokenMaps[lineIndex].size(); ++index) tokenMaps[lineIndex][index] = token;
		}
	}

	ts_tree_delete(tree);
	return tokenMaps;
}

MRTreeSitterDocument::Language MRTreeSitterDocument::activeLanguage() const noexcept {
	return mImpl != nullptr ? mImpl->language : Language::None;
}

bool MRTreeSitterDocument::hasTree() const noexcept {
	return mImpl != nullptr && mImpl->tree != nullptr;
}
