	r.b.y = r.a.y + 1;
	return new MRMenuBar(r, *createFileMenu() + *createEditMenu() + *buildWindowMenu() + *createBlockMenu() + *createSearchMenu() + *createTextMenu() + *createOtherMenu() + *createMacroMenu() + *createHelpMenu());
