void TEventViewer::write(opstream &os)
{
    // TTerminal does not override the TStreamable methods, so do not
    // store it in the stream.
    title = 0;
    remove(scrollBar);
    remove(interior);
    TWindow::write(os);
    title = titles[stopped];
    insert(scrollBar);
    insert(interior);

    os << bufSize;
}

void *TEventViewer::read(ipstream &is)
{
    TWindow::read(is);

    ushort aBufSize;
    is >> aBufSize;
    init(aBufSize);
    return this;
}

