/*
 * Help compiler global variables.
 */
int           ofs;
int           bufferSize = 0;
char          textName[MAXPATH];
uchar         *buffer = 0;
TCrossRefNode *xRefs;
TRefTable     *refTable = 0;
char          line[MAXSTRSIZE] = "";
Boolean       lineInBuffer = False;
int           lineCount = 0;

