void TCluster::moveSel(int i, int s)
{
    if (i <= strings->getCount())
    {
        sel = s;
        movedTo(sel);
        drawView();
    }
}

void TCluster::handleEvent( TEvent& event )
{
    TView::handleEvent(event);
    if (!(options & ofSelectable))
        return;
    if( event.what == evMouseDown )
        {
        TPoint mouse = makeLocal( event.mouse.where );
        int i = findSel(mouse);
        if( (i != -1) && buttonState(i))
            sel = i;
        drawView();
        do  {
            mouse = makeLocal( event.mouse.where );
            if( (findSel(mouse) == sel ) && buttonState(sel))
                showCursor();
            else
                hideCursor();
            } while( mouseEvent(event,evMouseMove) );
        showCursor();
        mouse = makeLocal( event.mouse.where );
        if( findSel(mouse) == sel )
            {
            press(sel);
            drawView();
            }
        clearEvent(event);
        }
    else if( event.what == evKeyDown )
    {
        int s = sel;
        switch (ctrlToArrow(event.keyDown.keyCode))
            {
            case kbUp:
                if( (state & sfFocused) != 0 )
                    {
                    int i = 0;
                    do  {
                        i++; s--;
                        if (s < 0)
                            s = strings->getCount()-1;
                        } while (!(buttonState(s) || (i > strings->getCount())));
                    moveSel(i, s);
                    clearEvent(event);
                    }
                break;
            case kbDown:
                if( (state & sfFocused) != 0 )
                    {
                    int i = 0;
                    do  {
                        i++; s++;
                        if (s >= strings->getCount())
                            s = 0;
                        } while (!(buttonState(s) || (i > strings->getCount())));
                    moveSel(i, s);
                    clearEvent(event);
                    }
                break;
            case kbRight:
                if( (state & sfFocused) != 0 )
                    {
                    int i = 0;
                    do  {
                        i++; s += size.y;
                        if (s >= strings->getCount() )
                            s = 0;
                        } while (!(buttonState(s) || (i > strings->getCount())));
                    moveSel(i, s);
                    clearEvent(event);
                    }
                break;
            case kbLeft:
                if( (state & sfFocused) != 0 )
                    {
                    int i = 0;
                    do  {
                        i++;
                        if ( s > 0 )
                            {
                            s -= size.y;
                            if ( s < 0 )
                                {
                                s = ((strings->getCount()+size.y-1)/
                                    size.y)*size.y + s - 1;
                                if( s >= strings->getCount() )
                                    s = strings->getCount()-1;
                                }
                            }
                        else
                            s = strings->getCount()-1;
                        } while (!(buttonState(s) || (i > strings->getCount())));
                    moveSel(i, s);
                    clearEvent(event);
                    }
                break;
            default:
                for( int i = 0; i < strings->getCount(); i++ )
                    {
                    char c = hotKey( (char *)(strings->at(i)) );
                    if( event.keyDown.keyCode != 0 &&
                        ( getAltCode(c) == event.keyDown.keyCode ||
                          ( ( owner->phase == phPostProcess ||
                              (state & sfFocused) != 0
                            ) &&
                            c != 0 &&
                            c == (char) toupper(event.keyDown.charScan.charCode)
                          )
                        )
                      )
                        {
                        if (buttonState(i))
                            {
                            if (focus())
                                {
                                sel = i;
                                movedTo(sel);
                                press(sel);
                                drawView();
                                }
                            clearEvent(event);
                            }
                        return;
                        }
                    }
                if( event.keyDown.charScan.charCode == ' ' &&
                    (state & sfFocused) != 0
                  )
                    {
                    press(sel);
                    drawView();
                    clearEvent(event);
                    }
            }
    }
}


void TCluster::setButtonState(uint32_t aMask, Boolean enable)
{
    if (!enable)
        enableMask &= ~aMask;
    else
        enableMask |= aMask;

    int n = strings->getCount();
    if ( n < 32 )
    {
        uint32_t testMask = (1 << n) - 1;
        if ((enableMask & testMask) != 0)
            options |= ofSelectable;
        else
            options &= ~ofSelectable;
    }
}


