TPalette& TDialog::getPalette() const
{
    static TPalette paletteGray( cpGrayDialog, sizeof( cpGrayDialog )-1 );
    static TPalette paletteBlue( cpBlueDialog, sizeof( cpBlueDialog )-1 );
    static TPalette paletteCyan( cpCyanDialog, sizeof( cpCyanDialog )-1 );

    switch (palette)
    {
       case dpGrayDialog:
          return paletteGray;
       case dpBlueDialog:
          return paletteBlue;
       case dpCyanDialog:
          return paletteCyan;
    }
    return paletteGray;
}

void TDialog::handleEvent(TEvent& event)
{
    TWindow::handleEvent(event);
    switch (event.what)
        {
        case evKeyDown:
            switch (event.keyDown.keyCode)
                {
                case kbEsc:
                    event.what = evCommand;
                    event.message.command = cmCancel;
                    event.message.infoPtr = 0;
                    putEvent(event);
                    clearEvent(event);
                    break;
                case kbEnter:
                    event.what = evBroadcast;
                    event.message.command = cmDefault;
                    event.message.infoPtr = 0;
                    putEvent(event);
                    clearEvent(event);
                    break;
                }
            break;

        case evCommand:
            switch( event.message.command )
                {
                case cmOK:
                case cmCancel:
                case cmYes:
                case cmNo:
                    if( (state & sfModal) != 0 )
                        {
                        endModal(event.message.command);
                        clearEvent(event);
                        }
                    break;
                }
            break;
        }
}

Boolean TDialog::valid( ushort command )
{
    if( command == cmCancel )
        return True;
    else
        return TGroup::valid( command );
}

