static std::ostream &operator<<(std::ostream &os, TSpan<const char32_t> span)
{
    for (char32_t ch : span)
    {
        char s[11];
        if (ch <= 0xFF)
            sprintf(s, "\\x%02X", ch);
        else if (ch <= 0xFFFF)
            sprintf(s, "\\u%04X", ch);
        else
            sprintf(s, "\\U%08X", ch);
        os << s;
    }
    return os;
}

