bool hasHelpFlag(int argc, char **argv) {
	for (int i = 1; argv != nullptr && i < argc; ++i) {
		const char *arg = argv[i];
		if (arg == nullptr) continue;
		if (std::strcmp(arg, "--help") == 0 || std::strcmp(arg, "-h") == 0) return true;
	}
	return false;
}
