int main(int argc, char **argv) {
	if (hasHelpFlag(argc, argv)) {
		std::cout << kMrEmbeddedHelpMarkdown;
		return 0;
	}
	mrvmSetProcessContext(argc, argv);
	loadDefaultMultiEditPalette();
	MREditorApp app;
	app.run();
	return 0;
}
