#include "../config/MRDialogPaths.hpp"

namespace {
constexpr unsigned char kPaletteDialogSelector = 58;

TAttrPair configuredPaletteSlotOr(TView *view, unsigned char paletteSlot, ushort fallbackColorIndex) {
	unsigned char biosAttr = 0;

	if (configuredColorSlotOverride(paletteSlot, biosAttr)) return TAttrPair(biosAttr);
	return view != nullptr ? view->getColor(fallbackColorIndex) : TAttrPair(0x70);
}
} // namespace

MRNumericSlider::MRNumericSlider(const TRect &bounds, int32_t aMin, int32_t aMax, int32_t aValue, int32_t aStep, int32_t aPageStep, Format aFormat, ushort aChangedCmd) noexcept : TView(bounds), minValue(std::min(aMin, aMax)), maxValue(std::max(aMin, aMax)), value(0), step(absOrOne(aStep)), pageStep(aPageStep ? absOrOne(aPageStep) : absOrOne(aStep) * 10), textWidth(1), format(aFormat), changedCmd(aChangedCmd) {

	options |= ofSelectable;
	eventMask |= evMouseDown | evMouseWheel;
	recalcMetrics();
	setValueInternal(aValue, False, False);
}

void MRNumericSlider::draw() {
	TDrawBuffer b;
	const Boolean disabled = getState(sfDisabled);
	const Boolean focused = getState(sfFocused) && !disabled;

	const TAttrPair cTrack = disabled ? TAttrPair(mapColor(5)) : focused ? TAttrPair(mapColor(2)) : TAttrPair(mapColor(1));
	const TAttrPair cHandle = disabled ? TAttrPair(mapColor(5)) : configuredPaletteSlotOr(this, kPaletteDialogSelector, focused ? 2 : 1);
	const char *trackGlyph = disabled ? "·" : focused ? "═" : "─";

	b.moveChar(0, ' ', cTrack, size.x);

	const int hw = handleWidth();
	const int hp = handlePosFromValue(value);

	for (int x = 0; x < hp; ++x)
		b.moveStr((ushort)x, trackGlyph, cTrack, 1);
	for (int x = hp + hw; x < size.x; ++x)
		b.moveStr((ushort)x, trackGlyph, cTrack, 1);

	std::array<char, 32> num{};
	std::array<char, 48> handle{};
	formatValue(num.data(), num.size(), value);
	std::snprintf(handle.data(), handle.size(), "◄%s►", num.data());
	b.moveStr((ushort)hp, handle.data(), cHandle, (ushort)hw);

	writeLine(0, 0, size.x, 1, b);
}

void MRNumericSlider::handleEvent(TEvent &event) {
	if (!getState(sfDisabled)) {
		if (event.what == evMouseDown && containsMouse(event)) {
			select();
			drag(event);
			clearEvent(event);
			return;
		}

		if (event.what == evMouseWheel && containsMouse(event)) {
			switch (event.mouse.wheel) {
				case mwUp:
				case mwRight:
					changeBy(step);
					clearEvent(event);
					return;
				case mwDown:
				case mwLeft:
					changeBy(-step);
					clearEvent(event);
					return;
			}
		}

		if (event.what == evKeyDown) {
			switch (event.keyDown.keyCode) {
				case kbLeft:
				case kbDown:
					changeBy(-step);
					clearEvent(event);
					return;
				case kbRight:
				case kbUp:
					changeBy(step);
					clearEvent(event);
					return;
				case kbPgDn:
					changeBy(-pageStep);
					clearEvent(event);
					return;
				case kbPgUp:
					changeBy(pageStep);
					clearEvent(event);
					return;
				case kbHome:
					setValueInternal(minValue, True, True);
					clearEvent(event);
					return;
				case kbEnd:
					setValueInternal(maxValue, True, True);
					clearEvent(event);
					return;
			}
		}
	}
	TView::handleEvent(event);
}

void MRNumericSlider::sizeLimits(TPoint &min, TPoint &max) {
	TView::sizeLimits(min, max);
	min.x = std::max<short>(min.x, handleWidth() + 2);
	min.y = std::max<short>(min.y, 1);
	max.y = 1;
}

ushort MRNumericSlider::dataSize() {
	return sizeof(int32_t);
}

void MRNumericSlider::getData(void *rec) {
	if (rec) *static_cast<int32_t *>(rec) = value;
}

void MRNumericSlider::setData(void *rec) {
	if (rec) setValueInternal(*static_cast<const int32_t *>(rec), True, False);
}

void MRNumericSlider::setState(ushort aState, Boolean enable) {
	const ushort old = state;
	TView::setState(aState, enable);
	if (old != state && (aState & (sfFocused | sfDisabled | sfSelected | sfActive))) drawView();
}

TColorAttr MRNumericSlider::mapColor(uchar index) {
	if (owner) {
		switch (index) {
			case 1:
				return owner->mapColor(4); // passive track
			case 2:
				return owner->mapColor(5); // focused track
			case 3:
			case 4:
				return owner->mapColor(1); // unused in draw(); handle color is resolved directly via configured palette slot.
			case 5:
				return owner->mapColor(13); // disabled
		}
	}
	switch (index) {
		case 1:
			return TColorAttr(0x08);
		case 2:
			return TColorAttr(0x09);
		case 3:
		case 4:
			return TColorAttr(0x70);
		case 5:
			return TColorAttr(0x07);
		default:
			return TView::mapColor(index);
	}
}

void MRNumericSlider::setValue(int32_t aValue) noexcept {
	setValueInternal(aValue, True, False);
}

void MRNumericSlider::setRange(int32_t aMin, int32_t aMax) noexcept {
	if (aMin > aMax) std::swap(aMin, aMax);
	minValue = aMin;
	maxValue = aMax;
	recalcMetrics();
	setValueInternal(value, True, False);
}

void MRNumericSlider::setStep(int32_t aStep) noexcept {
	step = absOrOne(aStep);
}

void MRNumericSlider::setPageStep(int32_t aPageStep) noexcept {
	pageStep = absOrOne(aPageStep);
}

void MRNumericSlider::setFormat(Format aFormat) noexcept {
	if (format != aFormat) {
		format = aFormat;
		recalcMetrics();
		drawView();
	}
}

int32_t MRNumericSlider::absOrOne(int32_t v) noexcept {
	return v == 0 ? 1 : (v < 0 ? -v : v);
}

int32_t MRNumericSlider::clamp64(int64_t v, int32_t lo, int32_t hi) noexcept {
	return static_cast<int32_t>(std::clamp(v, static_cast<int64_t>(lo), static_cast<int64_t>(hi)));
}

int MRNumericSlider::trackSpan() const noexcept {
	return std::max(0, size.x - handleWidth());
}

int MRNumericSlider::handlePosFromValue(int32_t v) const noexcept {
	const int span = trackSpan();
	if (span <= 0 || maxValue <= minValue) return 0;

	const int64_t num = int64_t(v - minValue) * span;
	const int64_t den = int64_t(maxValue - minValue);
	return (int)((num + den / 2) / den);
}

int32_t MRNumericSlider::valueFromHandlePos(int pos) const noexcept {
	const int span = trackSpan();
	if (span <= 0 || maxValue <= minValue) return minValue;

	pos = std::clamp(pos, 0, span);
	const int64_t num = int64_t(pos) * (maxValue - minValue);
	return minValue + (int32_t)((num + span / 2) / span);
}

int32_t MRNumericSlider::valueFromMouseX(int x, int dragOffset) const noexcept {
	return valueFromHandlePos(x - dragOffset);
}

void MRNumericSlider::recalcMetrics() noexcept {
	textWidth = calcTextWidth();
}

int MRNumericSlider::calcTextWidth() const noexcept {
	std::array<char, 32> minText{};
	std::array<char, 32> maxText{};
	formatValue(minText.data(), minText.size(), minValue);
	formatValue(maxText.data(), maxText.size(), maxValue);
	return std::max<int>(1, std::max(std::strlen(minText.data()), std::strlen(maxText.data())));
}

void MRNumericSlider::formatValue(char *dst, size_t dstSize, int32_t v) const noexcept {
	if (!dst || dstSize == 0) return;

	if (format == fmtPercent) std::snprintf(dst, dstSize, "%d%%", (int)v);
	else if (minValue >= 0)
		std::snprintf(dst, dstSize, "%0*d", textWidth ? textWidth : 1, (int)v);
	else
		std::snprintf(dst, dstSize, "%*d", textWidth ? textWidth : 1, (int)v);
}

void MRNumericSlider::setValueInternal(int32_t aValue, Boolean redraw, Boolean notify) noexcept {
	const int32_t nv = clamp64(aValue, minValue, maxValue);
	const Boolean changed = nv != value;
	value = nv;
	if (redraw) drawView();
	if (changed && notify) notifyChanged();
}

void MRNumericSlider::changeBy(int32_t delta) noexcept {
	setValueInternal(clamp64(int64_t(value) + delta, minValue, maxValue), True, True);
}

void MRNumericSlider::drag(TEvent &event) noexcept {
	const int hp = handlePosFromValue(value);
	const int hw = handleWidth();
	TPoint p = makeLocal(event.mouse.where);
	int dragOffset = hw / 2;

	if (p.x >= hp && p.x < hp + hw) dragOffset = p.x - hp;
	else
		setValueInternal(valueFromMouseX(p.x, dragOffset), True, True);

	while (mouseEvent(event, evMouseMove | evMouseAuto | evMouseUp)) {
		if (event.what == evMouseUp) break;
		p = makeLocal(event.mouse.where);
		setValueInternal(valueFromMouseX(p.x, dragOffset), True, True);
	}
}

void MRNumericSlider::notifyChanged() noexcept {
	if (owner) message(owner, evBroadcast, changedCmd, this);
}#include "MRTextFormatting.hpp"

#include <algorithm>
#include <cctype>
#include <vector>

namespace {

std::vector<std::string> splitWords(std::string_view text) {
	std::vector<std::string> words;
	std::string currentWord;

	for (std::size_t i = 0; i <= text.length(); ++i) {
		if (i == text.length() || std::isspace(static_cast<unsigned char>(text[i])) != 0) {
			if (!currentWord.empty()) {
				words.push_back(currentWord);
				currentWord.clear();
			}
			continue;
		}
		currentWord.push_back(text[i]);
	}
	return words;
}

} // namespace

MRTextFormatting::NormalizedFormatLine MRTextFormatting::normalizedFormatLine(const MREditSetupSettings &settings) {
	NormalizedFormatLine normalized;

	normalized.leftMargin = settings.leftMargin;
	normalized.rightMargin = settings.rightMargin;
	if (!normalizeEditFormatLine(settings.formatLine, settings.tabSize, settings.leftMargin, settings.rightMargin, normalized.line, &normalized.leftMargin, &normalized.rightMargin, nullptr)) normalized.line = defaultEditFormatLineForTabSize(settings.tabSize, settings.leftMargin, settings.rightMargin);
	return normalized;
}

void MRTextFormatting::effectiveMargins(const MREditSetupSettings &settings, int &leftMargin, int &rightMargin) noexcept {
	std::string normalized;

	leftMargin = settings.leftMargin;
	rightMargin = settings.rightMargin;
	if (normalizeEditFormatLine(settings.formatLine, settings.tabSize, settings.leftMargin, settings.rightMargin, normalized, &leftMargin, &rightMargin, nullptr)) return;
	leftMargin = std::max(1, settings.leftMargin);
	rightMargin = std::max(leftMargin, settings.rightMargin > 0 ? settings.rightMargin : 78);
}

std::string MRTextFormatting::formatParagraphText(std::string_view paragraphText, int leftMargin, int rightMargin) {
	const int safeLeftMargin = std::max(1, leftMargin);
	const int safeRightMargin = std::max(safeLeftMargin, rightMargin);
	const std::size_t indentWidth = static_cast<std::size_t>(safeLeftMargin - 1);
	const std::size_t contentWidth = static_cast<std::size_t>(std::max(1, safeRightMargin - safeLeftMargin + 1));
	const std::vector<std::string> words = splitWords(paragraphText);
	std::string formattedText;
	std::string currentLine;
	std::size_t currentLineLength = 0;

	if (words.empty()) return std::string();
	for (const std::string &word : words) {
		const std::size_t projectedLength = currentLine.empty() ? word.size() : currentLineLength + 1 + word.size();
		if (!currentLine.empty() && projectedLength > contentWidth) {
			if (!formattedText.empty()) formattedText.push_back('\n');
			formattedText.append(indentWidth, ' ');
			formattedText += currentLine;
			currentLine = word;
			currentLineLength = word.size();
			continue;
		}
		if (!currentLine.empty()) {
			currentLine.push_back(' ');
			++currentLineLength;
		}
		currentLine += word;
		currentLineLength += word.size();
	}
	if (!currentLine.empty()) {
		if (!formattedText.empty()) formattedText.push_back('\n');
		formattedText.append(indentWidth, ' ');
		formattedText += currentLine;
	}
	return formattedText;
}

std::string MRTextFormatting::justifyParagraphText(std::string_view paragraphText, int leftMargin, int rightMargin) {
	const int safeLeftMargin = std::max(1, leftMargin);
	const int safeRightMargin = std::max(safeLeftMargin, rightMargin);
	const std::size_t indentWidth = static_cast<std::size_t>(safeLeftMargin - 1);
	const std::size_t contentWidth = static_cast<std::size_t>(std::max(1, safeRightMargin - safeLeftMargin + 1));
	const std::vector<std::string> words = splitWords(paragraphText);
	std::vector<std::vector<std::string>> lines;
	std::vector<std::string> currentLineWords;
	std::size_t currentLineLength = 0;
	std::string justifiedText;

	if (words.empty()) return std::string();
	for (const std::string &word : words) {
		const std::size_t projectedLength = currentLineWords.empty() ? word.size() : currentLineLength + 1 + word.size();
		if (!currentLineWords.empty() && projectedLength > contentWidth) {
			lines.push_back(currentLineWords);
			currentLineWords.clear();
			currentLineLength = 0;
		}
		if (!currentLineWords.empty()) ++currentLineLength;
		currentLineWords.push_back(word);
		currentLineLength += word.size();
	}
	if (!currentLineWords.empty()) lines.push_back(currentLineWords);
	for (std::size_t lineIndex = 0; lineIndex < lines.size(); ++lineIndex) {
		const bool lastLine = lineIndex + 1 == lines.size();
		std::size_t wordsLength = 0;
		std::string line(indentWidth, ' ');

		for (const std::string &word : lines[lineIndex])
			wordsLength += word.size();
		if (lastLine || lines[lineIndex].size() == 1) {
			for (std::size_t i = 0; i < lines[lineIndex].size(); ++i) {
				if (i != 0) line.push_back(' ');
				line += lines[lineIndex][i];
			}
		} else {
			const std::size_t gapCount = lines[lineIndex].size() - 1;
			const std::size_t totalSpaces = contentWidth > wordsLength ? contentWidth - wordsLength : gapCount;
			const std::size_t baseGap = totalSpaces / gapCount;
			const std::size_t extraGap = totalSpaces % gapCount;

			for (std::size_t i = 0; i < lines[lineIndex].size(); ++i) {
				if (i != 0) line.append(baseGap + (i <= extraGap ? 1 : 0), ' ');
				line += lines[lineIndex][i];
			}
		}
		if (!justifiedText.empty()) justifiedText.push_back('\n');
		justifiedText += line;
	}
	return justifiedText;
}
#include "MRTextViewport.hpp"

#include <algorithm>
#include <array>
#include <cctype>
#include <vector>

namespace {

struct GutterLayoutLane {
	int left = 0;
	int right = 0;

	explicit GutterLayoutLane(int width) noexcept : left(0), right(std::max(0, width)) {
	}

	bool placeLeading(int width, int &outX) noexcept {
		if (width <= 0 || width >= right - left) return false;
		outX = left;
		left += width;
		return true;
	}

	bool placeTrailing(int width, int &outX) noexcept {
		if (width <= 0 || width >= right - left) return false;
		right -= width;
		outX = right;
		return true;
	}
};

bool isGutterPositionLeading(const std::string &position) noexcept {
	return position == "LEADING";
}

bool isGutterPositionTrailing(const std::string &position) noexcept {
	return position == "TRAILING";
}

int normalizedMiniMapWidth(const MREditSetupSettings &settings) noexcept {
	if (!isGutterPositionLeading(settings.miniMapPosition) && !isGutterPositionTrailing(settings.miniMapPosition)) return 0;
	return std::max(2, std::min(settings.miniMapWidth, 20));
}

std::string normalizedGuttersOrder(const std::string &configured) {
	std::string normalized;
	std::array<bool, 3> seen = {false, false, false};
	for (char ch : configured) {
		switch (static_cast<unsigned char>(std::toupper(static_cast<unsigned char>(ch)))) {
			case 'L':
				if (!seen[0]) {
					normalized.push_back('L');
					seen[0] = true;
				}
				break;
			case 'C':
				if (!seen[1]) {
					normalized.push_back('C');
					seen[1] = true;
				}
				break;
			case 'M':
				if (!seen[2]) {
					normalized.push_back('M');
					seen[2] = true;
				}
				break;
			default:
				break;
		}
	}
	if (normalized.empty()) normalized = "LCM";
	return normalized;
}

int decimalDigits(std::size_t value) noexcept {
	int digits = 1;
	while (value >= 10) {
		value /= 10;
		++digits;
	}
	return digits;
}

int lineNumberWidthFor(const MRTextViewportLayout::Inputs &inputs, bool showLineNumbers) noexcept {
	if (!showLineNumbers) return 0;
	const int textRows = std::max(1, inputs.visibleRows);
	const std::size_t visibleEnd = static_cast<std::size_t>(std::max(inputs.deltaY, 0) + textRows);
	const std::size_t lines = inputs.exactLineCountKnown ? std::max<std::size_t>(inputs.exactLineCount, visibleEnd) : std::max<std::size_t>(inputs.estimatedLineCount, visibleEnd);
	return std::min(decimalDigits(std::max<std::size_t>(lines, 1)), std::max(0, inputs.viewWidth - 1));
}

} // namespace

bool MRTextViewportLayout::Geometry::containsTextX(long long x) const noexcept {
	return x >= textLeft && x < textRight;
}

bool MRTextViewportLayout::Geometry::containsTextPoint(long long x, long long y, int viewHeight) const noexcept {
	return containsTextX(x) && y >= topInset && y < topInset + viewHeight;
}

int MRTextViewportLayout::Geometry::textColumnFromLocalX(int localX) const noexcept {
	const int clampedRight = std::max(textLeft, textRight - 1);
	const int clampedX = std::max(textLeft, std::min(localX, clampedRight));
	return std::max(0, clampedX - textLeft) + deltaX;
}

long long MRTextViewportLayout::Geometry::localXFromVisualColumn(long long visualColumn) const noexcept {
	return visualColumn - deltaX + textLeft;
}

std::string MRTextViewportLayout::normalizedLineNumbersPosition(const MREditSetupSettings &settings) {
	if (isGutterPositionLeading(settings.lineNumbersPosition) || isGutterPositionTrailing(settings.lineNumbersPosition)) return settings.lineNumbersPosition;
	return settings.showLineNumbers ? std::string("LEADING") : std::string("OFF");
}

std::string MRTextViewportLayout::normalizedCodeFoldingPosition(const MREditSetupSettings &settings) {
	if (isGutterPositionLeading(settings.codeFoldingPosition) || isGutterPositionTrailing(settings.codeFoldingPosition)) return settings.codeFoldingPosition;
	return settings.codeFolding ? std::string("LEADING") : std::string("OFF");
}

MRTextViewportLayout::Geometry MRTextViewportLayout::geometryFor(const MREditSetupSettings &settings, const Inputs &inputs) noexcept {
	Geometry viewport;
	GutterLayoutLane lane(std::max(0, inputs.viewWidth));
	viewport.topInset = settings.formatRuler ? 1 : 0;
	const std::string lineNumbersPosition = normalizedLineNumbersPosition(settings);
	const std::string codeFoldingPosition = normalizedCodeFoldingPosition(settings);
	const bool lineNumbersLeading = lineNumbersPosition == "LEADING";
	const bool lineNumbersTrailing = lineNumbersPosition == "TRAILING";
	const bool codeFoldingLeading = codeFoldingPosition == "LEADING";
	const bool codeFoldingTrailing = codeFoldingPosition == "TRAILING";
	const int lineNumberWidth = lineNumberWidthFor(inputs, lineNumbersLeading || lineNumbersTrailing);
	const int codeFoldingWidth = codeFoldingLeading || codeFoldingTrailing ? 1 : 0;
	const int miniMapTotalWidth = normalizedMiniMapWidth(settings);
	const bool leadingMiniMap = miniMapTotalWidth > 0 && isGutterPositionLeading(settings.miniMapPosition);
	const bool trailingMiniMap = miniMapTotalWidth > 0 && isGutterPositionTrailing(settings.miniMapPosition);
	const std::string guttersOrder = normalizedGuttersOrder(settings.gutters);
	const auto gutterWidthFor = [&](char marker) noexcept -> int {
		switch (marker) {
			case 'L':
				return lineNumberWidth;
			case 'C':
				return codeFoldingWidth;
			case 'M':
				return miniMapTotalWidth;
			default:
				return 0;
		}
	};
	const auto enabledOnLeading = [&](char marker) noexcept -> bool {
		switch (marker) {
			case 'L':
				return lineNumbersLeading;
			case 'C':
				return codeFoldingLeading;
			case 'M':
				return leadingMiniMap;
			default:
				return false;
		}
	};
	const auto enabledOnTrailing = [&](char marker) noexcept -> bool {
		switch (marker) {
			case 'L':
				return lineNumbersTrailing;
			case 'C':
				return codeFoldingTrailing;
			case 'M':
				return trailingMiniMap;
			default:
				return false;
		}
	};
	const auto assignGutterPlacement = [&](char marker, int x, bool leadingSide) {
		switch (marker) {
			case 'L':
				viewport.lineNumberX = x;
				viewport.lineNumberWidth = lineNumberWidth;
				break;
			case 'C':
				viewport.codeFoldingX = x;
				viewport.codeFoldingWidth = codeFoldingWidth;
				break;
			case 'M':
				viewport.miniMapTotalWidth = miniMapTotalWidth;
				viewport.miniMapBodyWidth = std::max(1, miniMapTotalWidth - 1);
				if (leadingSide) {
					viewport.miniMapBodyX = x;
					viewport.miniMapInfoX = x + viewport.miniMapBodyWidth;
				} else {
					viewport.miniMapInfoX = x;
					viewport.miniMapBodyX = x + 1;
				}
				break;
			default:
				break;
		}
	};
	std::vector<char> leadingSequence;
	std::vector<char> trailingSequence;
	leadingSequence.reserve(3);
	trailingSequence.reserve(3);
	for (char marker : guttersOrder) {
		if (enabledOnLeading(marker)) leadingSequence.push_back(marker);
		if (enabledOnTrailing(marker)) trailingSequence.push_back(marker);
	}
	for (char marker : leadingSequence) {
		int width = gutterWidthFor(marker);
		int x = -1;
		if (width > 0 && lane.placeLeading(width, x)) assignGutterPlacement(marker, x, true);
	}
	for (auto it = trailingSequence.rbegin(); it != trailingSequence.rend(); ++it) {
		int width = gutterWidthFor(*it);
		int x = -1;
		if (width > 0 && lane.placeTrailing(width, x)) assignGutterPlacement(*it, x, false);
	}
	if (!leadingSequence.empty() && leadingSequence.back() == 'M') {
		int separatorX = -1;
		if (lane.placeLeading(1, separatorX)) viewport.miniMapSeparatorX = separatorX;
	}
	if (!trailingSequence.empty() && trailingSequence.front() == 'M') {
		int separatorX = -1;
		if (lane.placeTrailing(1, separatorX)) viewport.miniMapSeparatorX = separatorX;
	}
	if (lane.right <= lane.left) {
		lane.left = std::max(0, std::min(lane.left, std::max(0, inputs.viewWidth - 1)));
		lane.right = std::max(lane.left + 1, inputs.viewWidth);
	}
	viewport.textLeft = lane.left;
	viewport.textRight = std::max(viewport.textLeft + 1, std::min(lane.right, inputs.viewWidth));
	viewport.width = std::max(1, viewport.textRight - viewport.textLeft);
	viewport.gutterWidth = viewport.textLeft;
	viewport.rightInset = std::max(0, inputs.viewWidth - viewport.textRight);
	viewport.deltaX = inputs.deltaX;
	viewport.deltaY = inputs.deltaY;
	return viewport;
}

bool MRTextViewportLayout::shouldShowCursor(const Geometry &geometry, long long x, long long y, int viewHeight, bool viewActive, bool viewSelected) noexcept {
	return viewActive && viewSelected && geometry.containsTextPoint(x, y, viewHeight);
}
