namespace tvision
{

ConsoleCtl *ConsoleCtl::instance = nullptr;

ConsoleCtl &ConsoleCtl::getInstance() noexcept
{
    if (!instance)
        instance = new ConsoleCtl;
    return *instance;
}

void ConsoleCtl::destroyInstance() noexcept
{
    delete instance;
    instance = nullptr;
}

} // namespace tvision

