#define Uses_EventCodes
#define Uses_TKeys
#include <tvision/tv.h>

#include <iostream.h>
#include <iomanip.h>

#ifdef __BORLANDC__
typedef long fmtflags;
#else
typedef ios::fmtflags fmtflags;
#endif

struct TConstant
{
    ushort value;
    const char *name;
};

#define NM(x) { x, #x }
#define NMEND() { 0, 0 }

