namespace {
MRKeymapResolver g_runtimeKeymapResolver;

const MRKeymapProfile *findActiveProfile(std::span<const MRKeymapProfile> profiles, std::string_view activeProfileName) noexcept {
	for (const MRKeymapProfile &profile : profiles)
		if (profile.name == activeProfileName) return &profile;
	for (const MRKeymapProfile &profile : profiles)
		if (profile.name == "DEFAULT") return &profile;
	return profiles.empty() ? nullptr : &profiles.front();
}
} // namespace

bool MRKeymapResolver::isAbortToken(const MRKeymapToken &token) noexcept {
	return token.baseKey() == MRKeymapBaseKey::Esc && token.modifiers() == 0;
}

std::size_t MRKeymapResolver::contextIndex(MRKeymapContext context) noexcept {
	return static_cast<std::size_t>(context);
}

std::string MRKeymapResolver::sequenceText(std::span<const MRKeymapToken> tokens) {
	std::string text;

	for (const MRKeymapToken &token : tokens)
		text += token.toString();
	return text;
}

bool MRKeymapResolver::rebuild(std::span<const MRKeymapProfile> profiles, std::string_view activeProfileName, std::string *errorMessage) {
	const MRKeymapProfile *activeProfile = findActiveProfile(profiles, activeProfileName);
	const std::span<const MRKeymapBindingRecord> bindings = activeProfile != nullptr ? std::span<const MRKeymapBindingRecord>(activeProfile->bindings) : std::span<const MRKeymapBindingRecord>();

	resetPending();
	return trie.rebuild(bindings, errorMessage);
}

MRKeymapResolver::Result MRKeymapResolver::resolve(MRKeymapContext context, const MRKeymapToken &token) {
	Result result;
	PendingState *state = nullptr;

	result.context = context;
	if (context == MRKeymapContext::None) return result;
	state = &pendingStates[contextIndex(context)];
	if (!state->tokens.empty() && isAbortToken(token)) {
		result.kind = ResultKind::Aborted;
		result.sequenceText = sequenceText(state->tokens);
		state->tokens.clear();
		return result;
	}

	state->tokens.push_back(token);
	result.sequenceText = sequenceText(state->tokens);

	const MRKeymapTrie::Decision decision = trie.decide(context, state->tokens);
	switch (decision.kind) {
		case MRKeymapTrie::DecisionKind::Matched:
			result.kind = ResultKind::Matched;
			result.target = decision.target;
			result.description = decision.description;
			state->tokens.clear();
			return result;
		case MRKeymapTrie::DecisionKind::Pending:
			result.kind = ResultKind::Pending;
			return result;
		case MRKeymapTrie::DecisionKind::NoMatch:
			if (state->tokens.size() == 1) {
				state->tokens.clear();
				result.kind = ResultKind::NoMatch;
				return result;
			}
			state->tokens.clear();
			result.kind = ResultKind::Invalid;
			return result;
	}
	state->tokens.clear();
	return result;
}

bool MRKeymapResolver::hasPending(MRKeymapContext context) const noexcept {
	if (context == MRKeymapContext::None) return false;
	return !pendingStates[contextIndex(context)].tokens.empty();
}

void MRKeymapResolver::resetPending() noexcept {
	for (PendingState &state : pendingStates)
		state.tokens.clear();
}

MRKeymapResolver &runtimeKeymapResolver() noexcept {
	return g_runtimeKeymapResolver;
}

bool rebuildRuntimeKeymapResolver(std::string *errorMessage) {
	return g_runtimeKeymapResolver.rebuild(configuredKeymapProfiles(), configuredActiveKeymapProfile(), errorMessage);
}
#include "MRKeymapTrie.hpp"

#include <array>
#include <algorithm>

namespace {
constexpr std::size_t kContextCount = static_cast<std::size_t>(MRKeymapContext::Edit) + 1;

bool setTrieError(std::string *errorMessage, const std::string &message) {
	if (errorMessage != nullptr) *errorMessage = message;
	return false;
}
} // namespace

std::size_t MRKeymapTrie::contextIndex(MRKeymapContext context) noexcept {
	return static_cast<std::size_t>(context);
}

bool MRKeymapTrie::rebuild(std::span<const MRKeymapBindingRecord> bindings, std::string *errorMessage) {
	nodes.clear();
	nodes.emplace_back();
	roots.assign(kContextCount, 0);

	for (const MRKeymapBindingRecord &binding : bindings) {
		if (binding.context == MRKeymapContext::None) return setTrieError(errorMessage, "Keymap trie build failed: binding without context.");
		if (binding.sequence.empty()) return setTrieError(errorMessage, "Keymap trie build failed: binding without sequence.");
		if (binding.target.target.empty()) return setTrieError(errorMessage, "Keymap trie build failed: binding without target.");

		std::size_t nodeIndex = roots[contextIndex(binding.context)];
		if (nodeIndex == 0) {
			nodeIndex = nodes.size();
			nodes.emplace_back();
			roots[contextIndex(binding.context)] = nodeIndex;
		}

		for (const MRKeymapToken &token : binding.sequence.tokens()) {
			auto &edges = nodes[nodeIndex].edges;
			bool found = false;
			for (const Edge &edge : edges) {
				if (edge.token != token) continue;
				nodeIndex = edge.nextIndex;
				found = true;
				break;
			}
			if (found) continue;
			const std::size_t nextIndex = nodes.size();
			edges.push_back(Edge{token, nextIndex});
			nodes.emplace_back();
			nodeIndex = nextIndex;
		}

		Node &node = nodes[nodeIndex];
		if (node.terminal) return setTrieError(errorMessage, "Keymap trie build failed: duplicate sequence '" + binding.sequence.toString() + "'.");
		if (!node.edges.empty()) return setTrieError(errorMessage, "Keymap trie build failed: terminal/prefix collision at '" + binding.sequence.toString() + "'.");

		for (std::size_t i = 1; i < binding.sequence.size(); ++i) {
			std::vector<MRKeymapToken> prefixTokens(binding.sequence.tokens().begin(), binding.sequence.tokens().begin() + static_cast<std::ptrdiff_t>(i));
			Decision prefixDecision = decide(binding.context, prefixTokens);
			if (prefixDecision.kind == DecisionKind::Matched) return setTrieError(errorMessage, "Keymap trie build failed: prefix/terminal collision at '" + binding.sequence.toString() + "'.");
		}

		node.terminal = true;
		node.target = binding.target;
		node.description = binding.description;
	}

	if (errorMessage != nullptr) errorMessage->clear();
	return true;
}

MRKeymapTrie::Decision MRKeymapTrie::decide(MRKeymapContext context, std::span<const MRKeymapToken> sequence) const {
	Decision decision;

	if (context == MRKeymapContext::None || sequence.empty()) return decision;
	const std::size_t rootIndex = roots[contextIndex(context)];
	if (rootIndex == 0) return decision;

	std::size_t nodeIndex = rootIndex;
	for (const MRKeymapToken &token : sequence) {
		const auto &edges = nodes[nodeIndex].edges;
		bool found = false;
		for (const Edge &edge : edges) {
			if (edge.token != token) continue;
			nodeIndex = edge.nextIndex;
			found = true;
			break;
		}
		if (!found) return decision;
	}

	const Node &node = nodes[nodeIndex];
	if (node.terminal) {
		decision.kind = DecisionKind::Matched;
		decision.target = node.target;
		decision.description = node.description;
		return decision;
	}
	if (!node.edges.empty()) decision.kind = DecisionKind::Pending;
	return decision;
}
